class WorkoutSessionExportTest {
    private lateinit var database: TrainFlowDatabase
    private lateinit var freeGolden: Map<String, Any?>

    @After fun closeDatabase() {
        if (::database.isInitialized) database.close()
    }

    private fun freshDatabase() {
        if (::database.isInitialized) database.close()
        database = Room.inMemoryDatabaseBuilder(
            ApplicationProvider.getApplicationContext<Context>(), TrainFlowDatabase::class.java
        ).allowMainThreadQueries().build()
    }

    private fun bindFreeGolden(fixture: Fixture) {
        if (fixture.header.id == "s-F0") {
            val fixed = mutableObject(parse(GOLDEN_SESSION_JSON.getValue("s-F0")))
            mutableObject(fixed["session"])["planSnapshotJson"] = fixture.header.planSnapshotJson
            mutableObject(mutableArray(mutableObject(fixed["execution"])["phases"])[0])["phaseIdentity"] =
                parse(fixture.phases.single().phaseIdentityJson)
            freeGolden = fixed
        }
    }

    private suspend fun seedFixture(fixture: Fixture) {
        database.workoutSessionDao().insertSession(fixture.header)
        fixture.phases.forEach { database.canonicalTimelineHeartRateDao().insertPhaseInterval(it) }
    }

    private fun freeFixture(): Fixture {
        val planJson = freeFollowAlongSnapshot().toStorageJson()
        val prepared = (PlanSnapshotStorageV1Validator.prepare(planJson, WorkoutMode.FOLLOW_ALONG)
            as PreparedPlanSnapshotStorageV1Result.Valid).prepared
        val phase = freeFollowAlongPhase(prepared)
        return Fixture(
            header = WorkoutSessionEntity(
                id = "s-F0", mode = "follow_along", status = "completed", planSnapshotJson = planJson,
                startedAt = "2026-09-29T00:00:00Z", endedAt = "2026-09-29T00:00:03Z",
                totalElapsedSec = 3, effectiveElapsedSec = 3, pausedElapsedSec = 0,
                timelineVersion = 1, lastDurableOffsetMs = 3000L, lastMutationSequence = 1L,
                trustedEndOffsetMs = 3000L, terminalReason = "completed",
                displayMetadataContractVersion = 1,
                sessionDisplayMetadataJson = """{"displayMetadataContractVersion":1,"entries":[]}""",
                startLocalDate = "2026-09-29", startZoneId = "UTC", startUtcOffsetSeconds = 0L,
                timeMetadataSourceContractVersion = 1L
            ),
            phases = listOf(WorkoutPhaseIntervalEntity(
                "s-F0:p:0", "s-F0", 0, 0L, 3000L, 0L, 1L, null,
                "follow_along_action", phase.phaseIdentityJson
            )),
            title = "跟练", mode = "follow_along", displays = emptyList(), structures = emptyList()
        )
    }

    private suspend fun encode(
        ids: List<String>,
        unknownIds: List<String> = emptyList(),
        source: String = if (ids.size == 1) "single_session" else "calendar",
        startDate: LocalDate? = null,
        endDate: LocalDate? = null,
        generatedAt: Instant = GENERATED_AT,
        locale: String = "zh-CN"
    ): ByteArray {
        val bytes = ByteArrayOutputStream()
        val writer = OutputStreamWriter(bytes, Charsets.UTF_8)
        val encoder = WorkoutSessionExport(writer, WorkoutSessionExportSelection(
            source, startDate, endDate, null, null, ids, unknownIds
        ), generatedAt, locale)
        val repo = WorkoutSessionRepository(database)
        for (id in ids) encoder.writeSession(repo.readSessionStrict(id))
        encoder.finish()
        writer.flush()
        return bytes.toByteArray()
    }

    private fun emitCase(id: String, bytes: ByteArray) {
        val digest = MessageDigest.getInstance("SHA-256").digest(bytes)
        val hex = digest.joinToString("") { "%02x".format(it) }
        println("CASE|$id|${bytes.size}|$hex|${Base64.getEncoder().encodeToString(bytes)}")
    }

    private fun parse(bytes: ByteArray): Any? = parse(bytes.toString(Charsets.UTF_8))
    private fun parse(text: String): Any? = JsonReader(StringReader(text)).use { reader ->
        val result = readValue(reader)
        assertEquals(JsonToken.END_DOCUMENT, reader.peek())
        result
    }

    private fun readValue(reader: JsonReader): Any? = when (reader.peek()) {
        JsonToken.BEGIN_OBJECT -> {
            val values = linkedMapOf<String, Any?>()
            reader.beginObject()
            while (reader.hasNext()) {
                val name = reader.nextName()
                assertFalse("duplicate key: $name", values.containsKey(name))
                values[name] = readValue(reader)
            }
            reader.endObject()
            values
        }
        JsonToken.BEGIN_ARRAY -> {
            val values = mutableListOf<Any?>()
            reader.beginArray()
            while (reader.hasNext()) values.add(readValue(reader))
            reader.endArray()
            values
        }
        JsonToken.STRING -> reader.nextString()
        JsonToken.NUMBER -> BigDecimal(reader.nextString())
        JsonToken.BOOLEAN -> reader.nextBoolean()
        JsonToken.NULL -> { reader.nextNull(); null }
        else -> error("unexpected JSON token: ${reader.peek()}")
    }

    @Suppress("UNCHECKED_CAST")
    private fun obj(value: Any?): Map<String, Any?> = value as Map<String, Any?>
    @Suppress("UNCHECKED_CAST")
    private fun arr(value: Any?): List<Any?> = value as List<Any?>
    private fun root(bytes: ByteArray): Map<String, Any?> = obj(obj(parse(bytes))["trainFlowSessionExport"])
    private fun sessions(bytes: ByteArray): List<Any?> = arr(root(bytes)["sessions"])

    @Test fun encodesCanonicalFamiliesAndFrozenSelection() = runBlocking {
        val ordered = listOf("L", "C", "S", "F", "F0")
        for (key in ordered) {
            freshDatabase()
            val fixture = if (key == "F0") freeFixture() else fixtures.getValue(key)
            seedFixture(fixture)
            val bytes = encode(listOf(fixture.header.id))
            assertCanonicalFixture(bytes, fixture)
        }
        freshDatabase()
        val selection = listOf(freeFixture(), fixtures.getValue("S"), fixtures.getValue("L"),
            fixtures.getValue("F"), fixtures.getValue("C"))
        selection.forEach { seedFixture(it) }
        bindFreeGolden(selection.first())
        val ids = selection.map { it.header.id }
        val first = encode(ids)
        val second = encode(ids)
        assertArrayEquals(first, second)
        assertEquals(parse(goldenDocument(ids)), parse(first))
        assertEquals(ids, sessions(first).map { obj(obj(it)["session"])["sessionId"] })
        assertEquals(listOf(1, 5, 14, 8, 10), sessions(first).map {
            arr(obj(obj(it)["execution"])["phases"]).size
        })
        emitCase("V01-MULTI", first)
    }

    private fun assertCanonicalFixture(bytes: ByteArray, fixture: Fixture) {
        bindFreeGolden(fixture)
        assertEquals(parse(goldenDocument(listOf(fixture.header.id))), parse(bytes))
        val session = obj(obj(sessions(bytes).single())["session"])
        assertEquals(fixture.header.id, session["sessionId"])
        assertEquals(fixture.header.planSnapshotJson, session["planSnapshotJson"])
        assertEquals(fixture.header.mode, session["mode"])
        assertEquals("canonical_v1", session["timelineStatus"])
        val item = obj(sessions(bytes).single())
        val phases = arr(obj(item["execution"])["phases"])
        assertEquals(fixture.phases.size, phases.size)
        fixture.phases.forEachIndexed { index, expected ->
            val actual = obj(phases[index])
            assertEquals(BigDecimal(expected.sequence), actual["sequence"])
            assertEquals(BigDecimal(expected.startOffsetMs), actual["startOffsetMs"])
            assertEquals(BigDecimal(expected.endOffsetMs!!), actual["endOffsetMs"])
            assertEquals(BigDecimal(expected.startMutationSequence), actual["startMutationSequence"])
            assertEquals(BigDecimal(expected.endMutationSequence!!), actual["endMutationSequence"])
            assertEquals(expected.phaseKind, actual["phaseKind"])
            assertEquals(parse(expected.phaseIdentityJson), actual["phaseIdentity"])
            val display = obj(actual["display"])
            assertEquals(BigDecimal.ONE, display["displayContractVersion"])
            assertEquals("zh-CN", display["locale"])
            val named = fixture.displays.getOrNull(index)
            assertEquals(named?.status ?: "resolved", display["resolutionStatus"])
            assertEquals(named?.label ?: if (fixture.mode == "follow_along" && fixture.displays.isEmpty()) "跟练" else null,
                display["label"])
        }
        val heartRate = obj(item["heartRate"])
        assertEquals("not_recorded", heartRate["status"])
        assertNull(heartRate["recording"])
        assertNull(heartRate["originalAnalysis"])
        assertNull(heartRate["durationAudit"])
        assertEquals(emptyList<Any>(), heartRate["samples"])
    }

    @Test fun preservesLegacyPresenceAndTypedExecution() = runBlocking {
        val cases = listOf(
            legacyHeader("L-T", "timed", """{"title":"Legacy old","mode":"timed","blocks":[]}"""),
            legacyHeader("L-S", "strength", """{"title":"Legacy old","mode":"strength","blocks":[]}"""),
            legacyHeader("L-F", "follow_along", """{"title":"Legacy old","mode":"follow_along","blocks":[]}"""),
            legacyHeader("L-FN", "follow_along", """{"title":"Legacy old","mode":"follow_along","blocks":[],"planId":null,"preferences":null,"followAlong":null}"""),
            legacyHeader("L-FV", "follow_along", """{"title":"空 格 \"引号\" \\ 反斜杠\n换行","mode":"follow_along","blocks":[],"planId":"old-plan","preferences":{},"followAlong":{"preset":true,"coachMediaIds":[],"chapterIds":[],"timelineCueIds":[],"musicTrackIds":[]}}""", "old-plan")
        )
        for (header in cases) {
            freshDatabase()
            database.workoutSessionDao().insertSession(header)
            if (header.id == "L-S") seedExecution("L-S")
            val bytes = encode(listOf(header.id), listOf(header.id))
            assertEquals(parse(goldenDocument(listOf(header.id), listOf(header.id))), parse(bytes))
            val item = obj(sessions(bytes).single())
            val session = obj(item["session"])
            assertEquals(header.planSnapshotJson, session["planSnapshotJson"])
            assertEquals("legacy_incomplete", session["timelineStatus"])
            assertNull(session["timelineVersion"])
            assertNull(session["displayMetadata"])
            assertNull(session["canonicalSessionDurationMs"])
            assertEquals(emptyList<Any>(), obj(item["execution"])["phases"])
            if (header.id == "L-S") assertExecutionX(obj(item["execution"]))
            emitCase("V02-${header.id}", bytes)
        }
    }

    private fun legacyHeader(id: String, mode: String, plan: String, planId: String? = null) =
        WorkoutSessionEntity(id = id, planId = planId, mode = mode, status = "completed", planSnapshotJson = plan)

    private suspend fun seedExecution(id: String) {
        val kinds = listOf("prepare", "timed_work", "timed_rest", "strength_prepare_set", "strength_active_set",
            "strength_confirm_set", "strength_rest", "stretch", "completed")
        val steps = kinds.mapIndexed { i, kind ->
            val start = when (i) { 0 -> "2026-09-08T00:00:00+08:00"; 1 -> START; else -> "2026-09-07T16:00:0${i}Z" }
            SessionStepRecordEntity("row-$i", id, when (i) { 0 -> "s-b"; 1 -> "s-a"; else -> "s-$i" }, kind,
                if (i % 2 == 0) "block" else null, if (i % 2 == 0) "item" else null,
                if (i % 2 == 0) "set" else null, if (i % 2 == 0) "exercise" else null,
                start, if (i < 2) null else Instant.parse(start).plusSeconds(1).toString(), i % 2 == 0,
                when (i) { 0 -> 0; 1 -> null; else -> 1 }, if (i == 0) null else 10)
        }
        val extensionKeys = listOf(Triple(2, 0, 5), Triple(1, 1, 5), Triple(1, 0, 6), Triple(1, 0, 5))
        val extensions = listOf("e-d", "e-c", "e-b", "e-a").mapIndexed { i, recordId ->
            val (event, index, cumulative) = extensionKeys[i]
            TimedRestExtensionRecordEntity(recordId, id, "rest", index, if (i == 3) 1 else null,
                if (i == 3) "stage" else null, "休息", if (i == 3) "prev" else null, if (i == 3) "前阶段" else null,
                5, 10, 0, 10, cumulative, event)
        }
        val texts = listOf(null to null, "weight=0.0,kg|rep=fixed,1" to "weight=0.0,kg|reps=0",
            "weight=60.0,lb|rep=range,1,200" to "weight=62.5,lb|reps=9", "rep=fixed,200" to "reps=12",
            "weight=1.5,kg" to "weight=1.5,kg", "rep=range,8,12|weight=60.0,kg" to "reps=9|weight=62.5,kg",
            "rep=range,1,1" to "reps=0", "rep=range,200,200" to null)
        val sets = listOf("k-b", "k-c", "k-a", "k-d", "k-e", "k-f", "k-g", "k-h").mapIndexed { i, recordId ->
            StrengthSetRecordEntity(recordId, id, "exercise", if (i % 2 == 0) "set" else null,
                listOf(1, 0, 0, 2, 3, 4, 5, 6)[i], listOf("warmup", "working", "drop", "backoff")[i % 4],
                listOf("both", "left", "right", "alternating", null, null, null, null)[i], texts[i].first, texts[i].second,
                when (i) { 0 -> 0; 1 -> null; else -> 7 }, if (i == 0) null else 0,
                listOf("easy", "good", "hard", "form_breakdown", null, null, null, null)[i],
                if (i % 2 == 0) "old" else null, if (i % 2 == 0) "原始备注" else null)
        }
        val dao = database.workoutSessionDao()
        dao.upsertStepRecords(steps)
        dao.upsertTimedRestExtensionRecords(extensions)
        dao.upsertStrengthSetRecords(sets)
    }

    private fun assertExecutionX(execution: Map<String, Any?>) {
        val steps = arr(execution["sessionStepRecords"])
        val rests = arr(execution["timedRestExtensions"])
        val sets = arr(execution["strengthSetRecords"])
        assertEquals(9, steps.size)
        assertEquals(4, rests.size)
        assertEquals(8, sets.size)
        assertEquals(listOf("s-a", "s-b") + (2..8).map { "s-$it" }, steps.map { obj(it)["stepId"] })
        assertEquals(listOf("e-a", "e-b", "e-c", "e-d"), rests.map { obj(it)["recordId"] })
        assertEquals(listOf("k-a", "k-c", "k-b", "k-d", "k-e", "k-f", "k-g", "k-h"),
            sets.map { obj(it)["recordId"] })
        assertFalse(obj(sets[0]).containsKey("notes"))
        val range = obj(obj(sets[0])["plannedRepTarget"])
        assertEquals("range", range["kind"])
        assertEquals(BigDecimal.ONE, range["minReps"])
        assertEquals(BigDecimal(200), range["maxReps"])
        assertEquals(BigDecimal("60.0"), obj(obj(sets[0])["plannedWeight"])["value"])
        assertEquals("lb", obj(obj(sets[0])["plannedWeight"])["unit"])
        assertEquals(BigDecimal("62.5"), obj(obj(sets[0])["actualWeight"])["value"])
        assertEquals(BigDecimal(9), obj(sets[0])["actualReps"])
        assertEquals(BigDecimal.ZERO, obj(sets[1])["actualReps"])
        assertEquals(BigDecimal("0.0"), obj(obj(sets[1])["actualWeight"])["value"])
        assertNull(obj(sets[2])["actualReps"])
        assertNull(obj(sets[2])["actualWeight"])
    }

    @Test fun preservesFrozenTimeAndChecksSelection() = runBlocking {
        val strength = fixtures.getValue("S")
        val t01 = strength.copy(header = strength.header.copy(
            id = "T01", startedAt = "2024-02-29T15:59:59Z", endedAt = "2024-02-29T16:00:05Z",
            startLocalDate = "2024-02-29", startZoneId = "Asia/Shanghai", startUtcOffsetSeconds = 28_800L
        ), phases = strength.phases.map { it.copy(sessionId = "T01", id = it.id.replace("s-S", "T01")) })
        val t02 = strength.copy(header = strength.header.copy(
            id = "T02", startedAt = "2025-12-31T18:14:59Z", endedAt = "2025-12-31T18:15:05Z",
            startLocalDate = "2025-12-31", startZoneId = "Asia/Kathmandu", startUtcOffsetSeconds = 20_700L
        ), phases = strength.phases.map { it.copy(sessionId = "T02", id = it.id.replace("s-S", "T02")) })
        val t03 = strength
        val t05 = legacyHeader("T05", "timed", """{"title":"Legacy old","mode":"timed","blocks":[]}""").copy(
            startedAt = "2026-09-07T16:00:00Z", endedAt = "2026-09-07T16:00:12Z")
        val t06 = legacyHeader("T06", "follow_along", """{"title":"Legacy old","mode":"follow_along","blocks":[]}""")
        val oldZone = java.util.TimeZone.getDefault()
        try {
            java.util.TimeZone.setDefault(java.util.TimeZone.getTimeZone("America/Los_Angeles"))
            freshDatabase()
            seedFixture(t01)
            val bytes = encode(listOf("T01"), startDate = LocalDate.parse("2024-02-29"),
                endDate = LocalDate.parse("2024-02-29"))
            val session = obj(obj(sessions(bytes).single())["session"])
            val time = obj(session["timeMetadata"])
            assertEquals("2024-02-29", time["startLocalDate"])
            assertEquals("Asia/Shanghai", time["startZoneId"])
            assertEquals(BigDecimal(28_800), time["startUtcOffsetSeconds"])
            assertEquals("2024-02-29T16:00:05.000Z", time["trustedEndAtUtc"])
            emitCase("T01", bytes)
        } finally {
            java.util.TimeZone.setDefault(oldZone)
        }
        for ((id, fixture, date, expectedEnd) in listOf(
            Quad("T02", t02, "2025-12-31", "2025-12-31T18:15:05.000Z"),
            Quad("T03", t03, "2026-09-13", "2026-09-13T00:00:06.000Z")
        )) {
            freshDatabase()
            seedFixture(fixture)
            val bytes = encode(listOf(fixture.header.id), startDate = LocalDate.parse(date),
                endDate = LocalDate.parse(date))
            assertEquals(expectedEnd, obj(obj(obj(sessions(bytes).single())["session"])["timeMetadata"])["trustedEndAtUtc"])
            emitCase(id, bytes)
        }
        freshDatabase()
        seedH("H10")
        val t04 = encode(listOf("H10"))
        val t04Session = obj(obj(sessions(t04).single())["session"])
        assertNull(t04Session["endedAt"])
        assertEquals("2026-09-29T00:00:06.000Z", obj(t04Session["timeMetadata"])["trustedEndAtUtc"])
        emitCase("T04", t04)
        for ((id, header, expectedBasis) in listOf(
            Triple("T05", t05, "legacy_stored"), Triple("T06", t06, "unknown")
        )) {
            freshDatabase()
            database.workoutSessionDao().insertSession(header)
            val bytes = encode(listOf(header.id), listOf(header.id))
            val time = obj(obj(obj(sessions(bytes).single())["session"])["timeMetadata"])
            assertEquals(expectedBasis, time["startTimestampBasis"])
            assertEquals("unavailable", time["trustedEndAtBasis"])
            assertNull(time["trustedEndAtUtc"])
            emitCase(id, bytes)
        }
        selectionFailures()
    }

    private data class Quad(val id: String, val fixture: Fixture, val date: String, val end: String)

    private suspend fun selectionFailures() {
        freshDatabase()
        val known = fixtures.getValue("S")
        seedFixture(known)
        val unknown = legacyHeader("S-unknown", "timed", """{"title":"Legacy old","mode":"timed","blocks":[]}""")
        database.workoutSessionDao().insertSession(unknown)
        val knownResult = WorkoutSessionRepository(database).readSessionStrict(known.header.id)
        val unknownResult = WorkoutSessionRepository(database).readSessionStrict(unknown.id)
        val base = WorkoutSessionExportSelection("calendar", null, null, null, null,
            listOf(known.header.id), emptyList())
        fun construct(selection: WorkoutSessionExportSelection, time: Instant = GENERATED_AT, locale: String = "zh-CN") =
            WorkoutSessionExport(StringWriter(), selection, time, locale)
        val invalid = listOf(
            "S01" to base.copy(includedSessionIds = emptyList()),
            "S02" to base.copy(includedSessionIds = listOf(known.header.id, known.header.id)),
            "S03" to base.copy(startDateInclusive = LocalDate.parse("2026-09-13")),
            "S04" to base.copy(endDateInclusive = LocalDate.parse("2026-09-13")),
            "S05" to base.copy(startDateInclusive = LocalDate.parse("2026-09-14"), endDateInclusive = LocalDate.parse("2026-09-13")),
            "S06" to base.copy(modeFilter = emptySet()),
            "S07" to base.copy(planFilter = emptySet()),
            "S08" to base.copy(source = "__unsupported__"),
            "S09" to base.copy(modeFilter = setOf("__unsupported__")),
            "S12" to base.copy(includedUnknownDateSessionIds = listOf("absent")),
            "S13" to base.copy(includedSessionIds = listOf(known.header.id, unknown.id),
                includedUnknownDateSessionIds = listOf(unknown.id, unknown.id)),
            "S14" to base.copy(includedSessionIds = listOf(unknown.id, "other"),
                includedUnknownDateSessionIds = listOf("other", unknown.id))
        )
        invalid.forEach { (id, value) ->
            assertThrows(id, IllegalArgumentException::class.java) { construct(value) }
        }
        assertThrows("S10", IllegalArgumentException::class.java) { construct(base, locale = "") }
        assertThrows("S11", IllegalArgumentException::class.java) {
            construct(base, time = Instant.parse("2026-09-30T00:00:00.000000001Z"))
        }
        fun reject(id: String, selection: WorkoutSessionExportSelection, result: WorkoutSessionStrictReadResult) {
            val encoder = construct(selection)
            assertThrows(id, IllegalStateException::class.java) { encoder.writeSession(result) }
        }
        reject("S15", base.copy(includedSessionIds = listOf("other")), knownResult)
        reject("S16", base.copy(modeFilter = setOf("timed")), knownResult)
        reject("S17", base.copy(includedSessionIds = listOf(unknown.id),
            includedUnknownDateSessionIds = listOf(unknown.id), planFilter = setOf("plan-old")), unknownResult)
        reject("S18", base.copy(startDateInclusive = LocalDate.parse("2026-09-14"),
            endDateInclusive = LocalDate.parse("2026-09-14")), knownResult)
        reject("S19", base.copy(includedUnknownDateSessionIds = listOf(known.header.id)), knownResult)
        reject("S20", base.copy(includedSessionIds = listOf(unknown.id)), unknownResult)
    }

    @Test fun leavesStreamOwnershipAndFailureWithCaller() { runBlocking {
        freshDatabase()
        val fixture = freeFixture()
        seedFixture(fixture)
        val result = WorkoutSessionRepository(database).readSessionStrict(fixture.header.id)
        val selection = WorkoutSessionExportSelection("single_session", null, null, null, null,
            listOf(fixture.header.id), emptyList())
        val normal = ObservedWriter()
        val encoder = WorkoutSessionExport(normal, selection, GENERATED_AT, "zh-CN")
        encoder.writeSession(result)
        encoder.finish()
        assertEquals(0, normal.flushes)
        assertEquals(0, normal.closes)
        assertEquals(1, sessions(normal.text.toByteArray(Charsets.UTF_8)).size)
        normal.flush()
        assertEquals(1, normal.flushes)

        val firstError = IOException("first-write")
        val first = ObservedWriter(firstError)
        assertSame(firstError, assertThrows(IOException::class.java) {
            WorkoutSessionExport(first, selection, GENERATED_AT, "zh-CN")
        })
        assertEquals(1, first.writes)
        assertEquals(0, first.closes)

        val sessionError = IOException("session-write")
        val second = ObservedWriter(sessionError)
        second.failNext = false
        val failing = WorkoutSessionExport(second, selection, GENERATED_AT, "zh-CN")
        second.failNext = true
        assertSame(sessionError, assertThrows(IOException::class.java) { failing.writeSession(result) })
        assertEquals(0, second.closes)

        val incomplete = WorkoutSessionExport(ObservedWriter(), selection, GENERATED_AT, "zh-CN")
        assertThrows(IllegalStateException::class.java) { incomplete.finish() }
        assertThrows(IllegalStateException::class.java) { encoder.writeSession(result) }
    } }

    private class ObservedWriter(private val failure: IOException? = null) : Writer() {
        private val buffer = StringBuilder()
        var writes = 0
        var flushes = 0
        var closes = 0
        var failNext = failure != null
        val text: String get() = buffer.toString()
        override fun write(chars: CharArray, offset: Int, length: Int) {
            writes++
            if (failNext) {
                failNext = false
                throw failure!!
            }
            buffer.append(chars, offset, length)
        }
        override fun flush() { flushes++ }
        override fun close() { closes++ }
    }

    @Test fun explainsEveryFieldAndVocabulary() = runBlocking {
        freshDatabase()
        val fixture = freeFixture()
        seedFixture(fixture)
        val exported = root(encode(listOf(fixture.header.id)))
        val dictionary = obj(exported["dataDictionary"])
        assertEquals(expectedDictionary, dictionary)
        val fields = arr(dictionary["fields"]).map(::obj)
        val rules = arr(dictionary["rules"]).map(::obj)
        assertEquals(784, fields.size)
        assertEquals(46, rules.size)
        assertEquals(385, fields.sumOf { arr(it["enumValues"]).size })
        assertEquals(fields.size, fields.map { it["path"] to it["condition"] }.toSet().size)
        assertEquals(listOf("followAlong", "planId", "preferences"), fields.filter {
            it["presence"] == "optional_nullable"
        }.map { (it["path"] as String).substringAfterLast('.') }.sorted())
        val ruleIds = rules.map { it["id"] as String }
        assertEquals(ruleIds.sorted(), ruleIds)
        assertEquals(46, ruleIds.toSet().size)
    }

    private val expectedDictionary: Any? by lazy { parse(EXPECTED_DICTIONARY_JSON) }

    private fun goldenDocument(ids: List<String>, unknown: List<String> = emptyList()): ByteArray {
        val items = ids.map { if (it == "s-F0") freeGolden else parse(GOLDEN_SESSION_JSON.getValue(it)) }
        val envelope = linkedMapOf<String, Any?>(
            "exportContractVersion" to BigDecimal(2), "generatedAt" to "2026-09-30T00:00:00.000Z",
            "displayLocale" to "zh-CN", "displayContractVersion" to BigDecimal.ONE,
            "selection" to linkedMapOf("source" to if (ids.size == 1) "single_session" else "calendar",
                "startDateInclusive" to null, "endDateInclusive" to null, "modeFilter" to null,
                "planFilter" to null, "includedSessionIds" to ids,
                "includedUnknownDateSessionIds" to unknown, "selectionScope" to "user_selected_subset"),
            "dataDictionary" to expectedDictionary, "sessions" to items
        )
        return jsonText(linkedMapOf("trainFlowSessionExport" to envelope)).toByteArray(Charsets.UTF_8)
    }

    private class FormatProblem(val path: String) : IllegalArgumentException(path)

    private fun formatCheck(ok: Boolean, path: String) {
        if (!ok) throw FormatProblem(path)
    }

    private fun jsonText(value: Any?): String {
        val out = StringWriter()
        JsonWriter(out).use { writer -> writeJsonValue(writer, value) }
        return out.toString()
    }

    private fun writeJsonValue(writer: JsonWriter, value: Any?) {
        when (value) {
            null -> writer.nullValue()
            is Map<*, *> -> {
                writer.beginObject()
                for ((key, item) in value) {
                    writer.name(key as String)
                    writeJsonValue(writer, item)
                }
                writer.endObject()
            }
            is List<*> -> {
                writer.beginArray()
                value.forEach { writeJsonValue(writer, it) }
                writer.endArray()
            }
            is String -> writer.value(value)
            is Boolean -> writer.value(value)
            is Number -> writer.value(value)
            else -> error("test JSON type: $value")
        }
    }

    private fun mutableCopy(value: Any?): Any? = when (value) {
        is Map<*, *> -> linkedMapOf<String, Any?>().also { copy ->
            value.forEach { (key, item) -> copy[key as String] = mutableCopy(item) }
        }
        is List<*> -> value.mapTo(mutableListOf()) { mutableCopy(it) }
        else -> value
    }

    @Suppress("UNCHECKED_CAST")
    private fun mutableObject(value: Any?): MutableMap<String, Any?> = value as MutableMap<String, Any?>
    @Suppress("UNCHECKED_CAST")
    private fun mutableArray(value: Any?): MutableList<Any?> = value as MutableList<Any?>

    private fun at(root: Any?, pointer: List<Any>): Any? {
        var node = root
        for (step in pointer) node = when (step) {
            is String -> obj(node)[step]
            is Int -> arr(node)[step]
            else -> error("pointer")
        }
        return node
    }

    private val fixedFieldIndex: Map<String, List<Map<String, Any?>>> by lazy {
        arr(obj(expectedDictionary)["fields"]).map(::obj).groupBy { it["path"] as String }
    }

    private fun formatEntries(path: String): List<Map<String, Any?>> = fixedFieldIndex[path].orEmpty()

    private fun minimumNonNull(entry: Map<String, Any?>): Any = when {
        (entry["type"] as String).startsWith("integer") || (entry["type"] as String).startsWith("number") -> BigDecimal.ZERO
        (entry["type"] as String).startsWith("string") -> ""
        (entry["type"] as String).startsWith("boolean") -> false
        (entry["type"] as String).startsWith("array") -> emptyList<Any>()
        (entry["type"] as String).startsWith("object") -> emptyMap<String, Any>()
        else -> error("fixed field type: ${entry["type"]}")
    }

    /** The reference document is assembled only from independent frozen literals and the approved F0 source. */
    private fun readFixedFormat(bytes: ByteArray, fixedSample: ByteArray) {
        val value = parse(bytes)
        val sample = parse(fixedSample)
        checkFixedShape(value, sample, "$")
        val envelope = obj(obj(value)["trainFlowSessionExport"])
        formatCheck(envelope["exportContractVersion"] == BigDecimal(2) &&
            envelope["displayContractVersion"] == BigDecimal.ONE,
            "$.trainFlowSessionExport.exportContractVersion")
        formatCheck(envelope["dataDictionary"] == expectedDictionary,
            "$.trainFlowSessionExport.dataDictionary")
        val selection = obj(envelope["selection"])
        formatCheck(selection["selectionScope"] == "user_selected_subset",
            "$.trainFlowSessionExport.selection.selectionScope")
        val ids = arr(selection["includedSessionIds"])
        val items = arr(envelope["sessions"]).map(::obj)
        formatCheck(ids.isNotEmpty() && ids.size == ids.toSet().size,
            "$.trainFlowSessionExport.selection.includedSessionIds")
        formatCheck(ids == items.map { obj(it["session"])["sessionId"] },
            "$.trainFlowSessionExport.sessions")
        val unknown = items.filter {
            obj(obj(it["session"])["timeMetadata"])["startLocalDate"] == null
        }.map { obj(it["session"])["sessionId"] }
        formatCheck(arr(selection["includedUnknownDateSessionIds"]) == unknown,
            "$.trainFlowSessionExport.selection.includedUnknownDateSessionIds")
        for (filter in listOf("modeFilter", "planFilter")) {
            val values = selection[filter]
            if (values != null) {
                val array = arr(values)
                formatCheck(array.isNotEmpty() && array.size == array.toSet().size,
                    "$.trainFlowSessionExport.selection.$filter")
                formatCheck(array == if (filter == "modeFilter")
                    listOf("timed", "strength", "follow_along").filter { it in array }
                else array.sortedBy { it as String }, "$.trainFlowSessionExport.selection.$filter")
            }
        }
        for ((index, item) in items.withIndex()) {
            val session = obj(item["session"])
            val modeFilter = selection["modeFilter"]
            val planFilter = selection["planFilter"]
            formatCheck(modeFilter == null || session["mode"] in arr(modeFilter),
                "$.trainFlowSessionExport.sessions[$index].session.mode")
            formatCheck(planFilter == null || session["planId"] in arr(planFilter),
                "$.trainFlowSessionExport.sessions[$index].session.planId")
            val phases = arr(obj(item["execution"])["phases"]).map(::obj)
            for ((phaseIndex, phase) in phases.withIndex()) {
                val display = obj(phase["display"])
                formatCheck(display["locale"] == envelope["displayLocale"],
                    "$.trainFlowSessionExport.sessions[$index].execution.phases[$phaseIndex].display.locale")
                formatCheck((display["resolutionStatus"] == "resolved") ==
                    ((display["label"] as String?)?.isNotEmpty() == true),
                    "$.trainFlowSessionExport.sessions[$index].execution.phases[$phaseIndex].display.label")
                val identity = obj(phase["phaseIdentity"])
                formatCheck(identity["mode"] == session["mode"] && identity["phaseKind"] == phase["phaseKind"],
                    "$.trainFlowSessionExport.sessions[$index].execution.phases[$phaseIndex].phaseIdentity")
            }
            val analysis = obj(item["heartRate"])["originalAnalysis"]
            val sets = arr(obj(item["execution"])["strengthSetRecords"]).map(::obj)
            for ((setIndex, set) in sets.withIndex()) {
                val rep = set["plannedRepTarget"]
                if (rep != null && obj(rep)["kind"] == "range") {
                    val target = obj(rep)
                    formatCheck((target["minReps"] as BigDecimal) <= (target["maxReps"] as BigDecimal),
                        "$.trainFlowSessionExport.sessions[$index].execution.strengthSetRecords[$setIndex].plannedRepTarget")
                }
            }
            if (analysis != null) {
                val recording = obj(obj(item["heartRate"])["recording"])
                val snapshot = obj(analysis)
                val audit = obj(obj(item["heartRate"])["durationAudit"])
                val intent = obj(audit["intentAxis"])
                val phase = obj(audit["phaseAxis"])
                val partition = obj(audit["primaryAnalysisPartition"])
                fun number(map: Map<String, Any?>, key: String) = map[key] as BigDecimal
                fun sum(map: Map<String, Any?>) = map.values.fold(BigDecimal.ZERO) { total, value ->
                    total + (value as BigDecimal)
                }
                val duration = number(audit, "canonicalSessionDurationMs")
                val window = number(audit, "recordingWindowDurationMs")
                val before = number(audit, "notRequestedBeforeRecordingStartMs")
                formatCheck(duration == before + number(intent, "userExcludedDurationMs") +
                    number(phase, "phaseExcludedDurationMs") + number(phase, "primaryEligibleDurationMs"),
                    "$.trainFlowSessionExport.sessions[$index].heartRate.durationAudit.DA01")
                formatCheck(window == duration - before,
                    "$.trainFlowSessionExport.sessions[$index].heartRate.durationAudit.DA02")
                formatCheck(number(intent, "expectedRecordingDurationMs") +
                    number(intent, "userExcludedDurationMs") == window,
                    "$.trainFlowSessionExport.sessions[$index].heartRate.durationAudit.DA03")
                formatCheck(number(intent, "userExcludedDurationMs") ==
                    number(intent, "userTurnedOffDurationMs") + number(intent, "userOptedOutDurationMs") +
                    number(intent, "userDisconnectedSuppressRecoveryDurationMs"),
                    "$.trainFlowSessionExport.sessions[$index].heartRate.durationAudit.DA04")
                formatCheck(number(phase, "phaseExcludedDurationMs") ==
                    number(phase, "strengthPrepareExcludedDurationMs") + number(phase, "pausedExcludedDurationMs"),
                    "$.trainFlowSessionExport.sessions[$index].heartRate.durationAudit.DA05")
                formatCheck(number(partition, "primaryEligibleDurationMs") ==
                    number(partition, "eligibleCoveredDurationMs") + number(partition, "eligibleUncoveredDurationMs") &&
                    number(partition, "primaryEligibleDurationMs") == number(phase, "primaryEligibleDurationMs") &&
                    number(partition, "primaryEligibleDurationMs") == snapshot["eligibleDurationMs"] &&
                    number(partition, "eligibleCoveredDurationMs") == snapshot["coveredDurationMs"],
                    "$.trainFlowSessionExport.sessions[$index].heartRate.durationAudit.DA06")
                formatCheck(sum(obj(audit["deviceStateDurations"])) == window,
                    "$.trainFlowSessionExport.sessions[$index].heartRate.durationAudit.DA07")
                formatCheck(sum(obj(audit["deviceReasonDurations"])) <= window,
                    "$.trainFlowSessionExport.sessions[$index].heartRate.durationAudit.DA08")
                formatCheck(recording["originalAnalysisVersion"] == snapshot["analysisVersion"] &&
                    recording["endedMutationSequence"] == snapshot["inputLastMutationSequence"],
                    "$.trainFlowSessionExport.sessions[$index].heartRate.originalAnalysis")
                formatCheck(snapshot["analysisConfig"] == parse(H_ANALYSIS_CONFIG),
                    "$.trainFlowSessionExport.sessions[$index].heartRate.originalAnalysis.analysisConfig")
                val highest = listOf("observedMaxBpm", "highestOffsetMs", "highestMutationSequence",
                    "highestSampleSequence").map { snapshot[it] }
                formatCheck(highest.all { it == null } || highest.all { it != null },
                    "$.trainFlowSessionExport.sessions[$index].heartRate.originalAnalysis.highestOffsetMs")
                if (highest.all { it != null }) {
                    val tuple = listOf("highestOffsetMs", "highestMutationSequence", "highestSampleSequence")
                        .map { snapshot[it] }
                    formatCheck(arr(obj(item["heartRate"])["samples"]).map(::obj).any { samplePoint ->
                        listOf("offsetMs", "mutationSequence", "sampleSequence")
                            .map { samplePoint[it] } == tuple && samplePoint["bpm"] == snapshot["observedMaxBpm"]
                    }, "$.trainFlowSessionExport.sessions[$index].heartRate.originalAnalysis.highestOffsetMs")
                }
                val id = session["sessionId"] as String
                if (id in H_SNAPSHOTS) {
                    val fixed = H_SNAPSHOTS.getValue(id)
                    formatCheck(obj(item["heartRate"])["durationAudit"] == parse(fixed.durationBreakdownJson),
                        "$.trainFlowSessionExport.sessions[$index].heartRate.durationAudit")
                    formatCheck(snapshot["qualityReasons"] == parse(fixed.qualityReasonsJson),
                        "$.trainFlowSessionExport.sessions[$index].heartRate.originalAnalysis.qualityReasons")
                }
            }
        }
    }

    private fun applicableEntries(path: String, ancestors: List<Map<String, Any?>>): List<Map<String, Any?>> =
        formatEntries(path).filter { entry ->
            val condition = entry["condition"] as String
            when {
                condition.startsWith("phaseIdentity.family=") -> {
                    val identity = ancestors.last { it.containsKey("family") && it.containsKey("payload") }
                    val payload = obj(identity["payload"])
                    condition.split("且").all { term ->
                        val (name, literal) = term.split("=", limit = 2)
                        when (name) {
                            "phaseIdentity.family" -> identity["family"] == literal
                            "payload.variant" -> payload["variant"] == literal
                            "payload.legacyBlockKind" -> payload["legacyBlockKind"] == literal
                            else -> error("fixed PH condition: $term")
                        }
                    }
                }
                condition.startsWith("本块kind") -> {
                    val kind = ancestors.last { it.containsKey("kind") }["kind"]
                    val literals = condition.substringAfter("kind").removePrefix("=").removePrefix("为").split("/")
                    kind in literals
                }
                condition.startsWith("此目标kind=") ->
                    ancestors.last { it.containsKey("kind") }["kind"] == condition.substringAfter("=")
                condition == "快照为canonical storage v1" ->
                    ancestors.last { it.containsKey("blocks") }.containsKey("planSnapshotStorageContractVersion")
                condition == "快照为legacy_unversioned" ->
                    !ancestors.last { it.containsKey("blocks") }.containsKey("planSnapshotStorageContractVersion")
                else -> condition == "always" || condition == "父对象存在且非null"
            }
        }

    private fun checkFixedShape(value: Any?, sample: Any?, path: String,
        ancestors: List<Map<String, Any?>> = emptyList()) {
        if (path == "$.trainFlowSessionExport.dataDictionary") {
            formatCheck(value == expectedDictionary, path)
            return
        }
        if (path.endsWith(".zoneSnapshot") ||
            path.endsWith(".zoneDurations")) {
            formatCheck(value == sample, path)
            return
        }
        when (sample) {
            is Map<*, *> -> {
                formatCheck(value is Map<*, *>, path)
                val actual = obj(value)
                val fixed = obj(sample)
                val context = ancestors + fixed
                for (key in actual.keys - fixed.keys) {
                    formatCheck(applicableEntries("$path.$key", context).any {
                        (it["presence"] as String).startsWith("optional")
                    }, "$path.$key")
                }
                for ((key, expected) in fixed) {
                    if (!actual.containsKey(key)) {
                        val legacyTriple = path.endsWith("planSnapshotJson::json") &&
                            !fixed.containsKey("planSnapshotStorageContractVersion") &&
                            key in setOf("planId", "preferences", "followAlong")
                        formatCheck(legacyTriple || applicableEntries("$path.$key", context).any {
                            it["presence"] == "optional_non_null"
                        }, "$path.$key")
                    } else checkFixedShape(actual[key], expected, "$path.$key", context)
                }
            }
            is List<*> -> {
                formatCheck(value is List<*>, path)
                val actual = arr(value)
                // Same repeated schema is tested on one representative; cardinality has its own relations.
                formatCheck(actual.size == sample.size, path)
                actual.forEachIndexed { index, item ->
                    checkFixedShape(item, sample[index], "$path[]", ancestors)
                }
            }
            null -> formatCheck(value == null, path)
            else -> {
                val entries = applicableEntries(path, ancestors)
                when (sample) {
                    is String -> formatCheck(value is String &&
                        (!entries.any { (it["type"] as String).contains("非空") } || value.isNotEmpty()), path)
                    is Boolean -> formatCheck(value is Boolean, path)
                    is Number -> formatCheck(value is BigDecimal, path)
                }
                if (value is BigDecimal && entries.any { (it["type"] as String).startsWith("integer") }) {
                    try { value.toBigIntegerExact().longValueExact() }
                    catch (_: ArithmeticException) { throw FormatProblem(path) }
                }
                val enums = entries.flatMap { arr(it["enumValues"]).map(::obj) }
                if (enums.isNotEmpty()) formatCheck(enums.any { it["value"] == value }, path)
                if (path.endsWith("Version")) formatCheck(value == sample, path)
                if (path.contains(".phaseIdentity.")) formatCheck(value == sample, path)
                if (path.endsWith("planSnapshotJson") && value is String && sample is String) {
                    checkFixedShape(parse(value), parse(sample), "$path::json", ancestors)
                }
            }
        }
    }

    private fun fixedMutation(
        id: String, sample: ByteArray, golden: ByteArray, pointer: List<Any>, key: String,
        change: (MutableMap<String, Any?>) -> Unit
    ): String {
        val altered = mutableCopy(parse(sample))
        val parent = mutableObject(at(altered, pointer))
        change(parent)
        val error = assertThrows(id, FormatProblem::class.java) {
            readFixedFormat(jsonText(altered).toByteArray(Charsets.UTF_8), golden)
        }
        assertTrue("$id failed without a path", error.path.isNotBlank())
        return error.path
    }

    private fun fixedPlanMutation(
        id: String, sample: ByteArray, golden: ByteArray, pointer: List<Any>,
        change: (MutableMap<String, Any?>) -> Unit
    ): String {
        val altered = mutableCopy(parse(sample))
        val session = mutableObject(at(altered,
            listOf("trainFlowSessionExport", "sessions", 0, "session")))
        val plan = mutableCopy(parse(session["planSnapshotJson"] as String))
        change(mutableObject(at(plan, pointer)))
        session["planSnapshotJson"] = jsonText(plan)
        val error = assertThrows(id, FormatProblem::class.java) {
            readFixedFormat(jsonText(altered).toByteArray(Charsets.UTF_8), golden)
        }
        return error.path
    }

