        val optionalBlocks = mutableArray(mutableObject(optionalPlan)["blocks"])
        optionalBlocks.map(::mutableObject).first { it["items"] is List<*> &&
            (it["items"] as List<*>).isNotEmpty() }.let {
            mutableObject(mutableArray(it["items"])[0]).remove("cueSettings")
        }
        optionalSession["planSnapshotJson"] = jsonText(optionalPlan)
        readFixedFormat(jsonText(optionalOmitted).toByteArray(Charsets.UTF_8), goldens.getValue("PL21-CUE"))
        val legacyOmitted = mutableCopy(parse(samples.getValue("L-FN")))
        val legacySession = mutableObject(at(legacyOmitted,
            listOf("trainFlowSessionExport", "sessions", 0, "session")))
        val legacyPlan = mutableCopy(parse(legacySession["planSnapshotJson"] as String))
        listOf("planId", "preferences", "followAlong").forEach { mutableObject(legacyPlan).remove(it) }
        legacySession["planSnapshotJson"] = jsonText(legacyPlan)
        readFixedFormat(jsonText(legacyOmitted).toByteArray(Charsets.UTF_8), goldens.getValue("L-FN"))

        val paths = linkedSetOf<String>()
        val failedPaths = linkedMapOf<String, String>()
        var count = 0
        fun probe(sample: ByteArray, golden: ByteArray, node: Any?, pointer: List<Any>, path: String,
            ancestors: List<Map<String, Any?>> = emptyList()) {
            when (node) {
                is Map<*, *> -> {
                    val values = obj(node)
                    if (path.contains("dataDictionary")) return
                    val context = ancestors + values
                    val shape = "$path|${values.keys.joinToString(",")}"
                    if (paths.add(shape)) {
                        val key = values.keys.firstOrNull()
                        if (key != null) {
                            val id = "V07-EXTRA-${++count}"
                            failedPaths[id] = fixedMutation(id, sample, golden, pointer, "__unexpected__") {
                                it["__unexpected__"] = false
                            }
                        }
                    }
                    for ((key, value) in values) {
                        val memberPath = "$path.$key"
                        if (!memberPath.startsWith("$.trainFlowSessionExport.dataDictionary")) {
                            formatCheck(formatEntries(memberPath).isNotEmpty(), memberPath)
                        }
                        val entry = applicableEntries(memberPath, context).single()
                        val identity = "$memberPath|${entry["condition"]}"
                        if (paths.add(identity)) {
                            val presence = listOf(entry["presence"] as String)
                            if (presence.none { it.startsWith("optional") }) {
                                val id = "V07-MISSING-${++count}"
                                failedPaths[id] = fixedMutation(id, sample, golden, pointer, key) { it.remove(key) }
                            }
                            if (value != null) {
                                val id = "V07-TYPE-${++count}"
                                val bad = if (value is Map<*, *> || value is List<*>) false else linkedMapOf<String, Any?>()
                                failedPaths[id] = fixedMutation(id, sample, golden, pointer, key) { it[key] = bad }
                                if (presence.any { it == "required_non_null" }) {
                                    val nullId = "V07-NULL-${++count}"
                                    failedPaths[nullId] = fixedMutation(nullId, sample, golden, pointer, key) { it[key] = null }
                                }
                                if (memberPath.endsWith("Version") && value is BigDecimal) {
                                    val versionId = "V07-VERSION-${++count}"
                                    failedPaths[versionId] = fixedMutation(versionId, sample, golden, pointer, key) {
                                        it[key] = value + BigDecimal.ONE
                                    }
                                }
                                if (value is String && arr(entry["enumValues"]).isNotEmpty()) {
                                    val enumId = "V07-ENUM-${++count}"
                                    failedPaths[enumId] = fixedMutation(enumId, sample, golden, pointer, key) {
                                        it[key] = "__unsupported__"
                                    }
                                }
                                if (memberPath.contains(".phaseIdentity.payload.") && value is BigDecimal &&
                                    !memberPath.endsWith("Version") && arr(entry["enumValues"]).isNotEmpty()) {
                                    val literalId = "V07-LITERAL-${++count}"
                                    failedPaths[literalId] = fixedMutation(literalId, sample, golden, pointer, key) {
                                        it[key] = value + BigDecimal.ONE
                                    }
                                }
                            } else {
                                val typeId = "V07-TYPE-${++count}"
                                val bad = if ((entry["type"] as String).startsWith("object") ||
                                    (entry["type"] as String).startsWith("array")) false else emptyMap<String, Any?>()
                                failedPaths[typeId] = fixedMutation(typeId, sample, golden, pointer, key) { it[key] = bad }
                                if (memberPath.contains(".phaseIdentity.payload.")) {
                                    val nullId = "V07-NULL-BRANCH-${++count}"
                                    failedPaths[nullId] = fixedMutation(nullId, sample, golden, pointer, key) {
                                        it[key] = minimumNonNull(entry)
                                    }
                                }
                            }
                        }
                        if (value is Map<*, *> || value is List<*>)
                            probe(sample, golden, value, pointer + key, memberPath, context)
                    }
                }
                is List<*> -> node.forEachIndexed { index, item ->
                    probe(sample, golden, item, pointer + index, "$path[]", ancestors)
                }
            }
        }
        samples.forEach { (id, bytes) ->
            val golden = goldens.getValue(id)
            probe(bytes, golden, parse(golden), emptyList(), "$")
        }
        fun probePlan(sample: ByteArray, golden: ByteArray, node: Any?, pointer: List<Any>, path: String,
            ancestors: List<Map<String, Any?>> = emptyList()) {
            when (node) {
                is Map<*, *> -> {
                    val values = obj(node)
                    val context = ancestors + values
                    val shape = "PLAN|$path|${values.keys.joinToString(",")}"
                    if (paths.add(shape)) {
                        val id = "V07-PL-EXTRA-${++count}"
                        failedPaths[id] = fixedPlanMutation(id, sample, golden, pointer) {
                            it["__unexpected__"] = false
                        }
                    }
                    for ((key, value) in values) {
                        val memberPath = "$path.$key"
                        formatCheck(formatEntries(memberPath).isNotEmpty(), memberPath)
                        val entry = applicableEntries(memberPath, context).single()
                        val identity = "PLAN|$memberPath|${entry["condition"]}"
                        if (paths.add(identity)) {
                            val presence = listOf(entry["presence"] as String)
                            val legacyTriple = path.endsWith("::json") &&
                                !values.containsKey("planSnapshotStorageContractVersion") &&
                                key in setOf("planId", "preferences", "followAlong")
                            if (!legacyTriple && presence.none { it.startsWith("optional") }) {
                                val id = "V07-PL-MISSING-${++count}"
                                failedPaths[id] = fixedPlanMutation(id, sample, golden, pointer) { it.remove(key) }
                            }
                            if (value != null) {
                                val id = "V07-PL-TYPE-${++count}"
                                val bad = if (value is Map<*, *> || value is List<*>) false else linkedMapOf<String, Any?>()
                                failedPaths[id] = fixedPlanMutation(id, sample, golden, pointer) { it[key] = bad }
                                if (presence.any { it == "required_non_null" || it == "optional_non_null" }) {
                                    val nullId = "V07-PL-NULL-${++count}"
                                    failedPaths[nullId] = fixedPlanMutation(nullId, sample, golden, pointer) { it[key] = null }
                                }
                                if (memberPath.endsWith("Version") && value is BigDecimal) {
                                    val versionId = "V07-PL-VERSION-${++count}"
                                    failedPaths[versionId] = fixedPlanMutation(versionId, sample, golden, pointer) {
                                        it[key] = value + BigDecimal.ONE
                                    }
                                }
                                if (value is String && arr(entry["enumValues"]).isNotEmpty()) {
                                    val enumId = "V07-PL-ENUM-${++count}"
                                    failedPaths[enumId] = fixedPlanMutation(enumId, sample, golden, pointer) {
                                        it[key] = "__unsupported__"
                                    }
                                }
                            } else {
                                val id = "V07-PL-TYPE-${++count}"
                                val bad = if ((entry["type"] as String).startsWith("object") ||
                                    (entry["type"] as String).startsWith("array")) false else emptyMap<String, Any?>()
                                failedPaths[id] = fixedPlanMutation(id, sample, golden, pointer) { it[key] = bad }
                            }
                        }
                        if (value is Map<*, *> || value is List<*>) {
                            probePlan(sample, golden, value, pointer + key, memberPath, context)
                        }
                    }
                }
                is List<*> -> node.forEachIndexed { index, item ->
                    probePlan(sample, golden, item, pointer + index, "$path[]", ancestors)
                }
            }
        }
        samples.filterKeys { it != "FORMAT-MULTI" }.forEach { (id, bytes) ->
            val golden = goldens.getValue(id)
            val plan = parse(obj(obj(sessions(golden).single())["session"])["planSnapshotJson"] as String)
            probePlan(bytes, golden, plan, emptyList(),
                "$.trainFlowSessionExport.sessions[].session.planSnapshotJson::json")
        }
        val base = samples.getValue("L")
        val dictionaryId = "V07-DICTIONARY-${++count}"
        failedPaths[dictionaryId] = fixedMutation(dictionaryId, base, goldens.getValue("L"),
            listOf("trainFlowSessionExport", "dataDictionary"), "fields") {
            mutableArray(it["fields"]).removeAt(0)
        }
        fun cross(sampleId: String, label: String, pointer: List<Any>, key: String,
            mutation: (MutableMap<String, Any?>) -> Unit) {
            val id = "V07-$label-${++count}"
            failedPaths[id] = fixedMutation(id, samples.getValue(sampleId), goldens.getValue(sampleId), pointer, key, mutation)
        }
        cross("L", "IDS-DUPLICATE", listOf("trainFlowSessionExport", "selection"),
            "includedSessionIds") {
            mutableArray(it["includedSessionIds"]).add("s-L")
        }
        cross("FORMAT-MULTI", "SESSION-ORDER", listOf("trainFlowSessionExport"), "sessions") {
            mutableArray(it["sessions"]).reverse()
        }
        cross("FORMAT-MULTI", "SELECTION-ORDER", listOf("trainFlowSessionExport", "selection"),
            "includedSessionIds") { mutableArray(it["includedSessionIds"]).reverse() }
        cross("L-T", "UNKNOWN-MISSING", listOf("trainFlowSessionExport", "selection"),
            "includedUnknownDateSessionIds") {
            mutableArray(it["includedUnknownDateSessionIds"]).clear()
        }
        cross("L", "UNKNOWN-EXTRA", listOf("trainFlowSessionExport", "selection"),
            "includedUnknownDateSessionIds") {
            mutableArray(it["includedUnknownDateSessionIds"]).add("s-L")
        }
        for (filter in listOf("modeFilter", "planFilter")) {
            cross("FORMAT-FILTER", "DUPLICATE-$filter",
                listOf("trainFlowSessionExport", "selection"), filter) {
                val values = mutableArray(it[filter]); values.add(values.first())
            }
        }
        cross("L", "DISPLAY-NULL", listOf("trainFlowSessionExport", "sessions", 0,
            "execution", "phases", 0, "display"), "label") { it["label"] = null }
        cross("L", "DISPLAY-LOCALE", listOf("trainFlowSessionExport", "sessions", 0,
            "execution", "phases", 0, "display"), "locale") { it["locale"] = "en-US" }
        cross("L", "DISPLAY-UNRESOLVED-LABEL", listOf("trainFlowSessionExport", "sessions", 0,
            "execution", "phases", 1, "display"), "label") { it["label"] = "假标题" }
        val identityPointer = listOf<Any>("trainFlowSessionExport", "sessions", 0,
            "execution", "phases", 0, "phaseIdentity")
        cross("L", "PH-FAMILY", identityPointer, "family") { it["family"] = "__unsupported__" }
        cross("L", "PH-MODE", identityPointer, "mode") { it["mode"] = "strength" }
        cross("L", "PH-KIND", identityPointer, "phaseKind") { it["phaseKind"] = "paused" }
        cross("L", "PH-SIGNATURE", identityPointer + "orderedStructureSignature", "digestHexLowercase") {
            it["digestHexLowercase"] = "0".repeat(64)
        }
        cross("L", "PH-VARIANT", identityPointer + "payload", "variant") {
            it["variant"] = "__unsupported__"
        }
        cross("L-S", "REP-RANGE", listOf("trainFlowSessionExport", "sessions", 0,
            "execution", "strengthSetRecords", 0, "plannedRepTarget"), "minReps") {
            it["minReps"] = BigDecimal(201)
        }
        cross("H06", "BINDING", listOf("trainFlowSessionExport", "sessions", 0,
            "heartRate", "originalAnalysis"), "inputLastMutationSequence") {
            it["inputLastMutationSequence"] = BigDecimal(99)
        }
        cross("H06", "HIGHEST-PARTIAL", listOf("trainFlowSessionExport", "sessions", 0,
            "heartRate", "originalAnalysis"), "highestOffsetMs") { it["highestOffsetMs"] = null }
        cross("H06", "HIGHEST-REFERENCE", listOf("trainFlowSessionExport", "sessions", 0,
            "heartRate", "originalAnalysis"), "highestOffsetMs") {
            it["highestOffsetMs"] = BigDecimal(999)
        }
        cross("H06", "ZONE-ORDER", listOf("trainFlowSessionExport", "sessions", 0,
            "heartRate", "recording", "zoneSnapshot"), "zones") {
            mutableArray(it["zones"]).reverse()
        }
        cross("H06", "ZONE-MISSING", listOf("trainFlowSessionExport", "sessions", 0,
            "heartRate", "recording", "zoneSnapshot"), "zones") {
            mutableArray(it["zones"]).removeAt(0)
        }
        cross("H06", "ZONE-BOUNDARY", listOf("trainFlowSessionExport", "sessions", 0,
            "heartRate", "recording", "zoneSnapshot", "zones", 1), "lowerBoundBasisPointsInclusive") {
            it["lowerBoundBasisPointsInclusive"] = BigDecimal(5001)
        }
        cross("H06", "ZONE-SUM", listOf("trainFlowSessionExport", "sessions", 0,
            "heartRate", "originalAnalysis", "zoneDurations"), "from60To70DurationMs") {
            it["from60To70DurationMs"] = BigDecimal(10_001)
        }
        val config = obj(obj(obj(sessions(samples.getValue("H06")).single())["heartRate"])["originalAnalysis"])
        val configKeys = obj(config["analysisConfig"]).keys.toList()
        for (key in configKeys) {
            cross("H06", "CONFIG-$key", listOf("trainFlowSessionExport", "sessions", 0,
                "heartRate", "originalAnalysis", "analysisConfig"), key) {
                it[key] = when (val old = it[key]) {
                    is BigDecimal -> old + BigDecimal.ONE
                    is Boolean -> !old
                    is String -> "__unsupported__"
                    else -> false
                }
            }
        }
        assertEquals("17 config literals", 17, configKeys.size)
        val audit = listOf(
            "DA01" to listOf("phaseAxis", "primaryEligibleDurationMs"),
            "DA02" to listOf("notRequestedBeforeRecordingStartMs"),
            "DA03" to listOf("recordingWindowDurationMs"),
            "DA04" to listOf("intentAxis", "userDisconnectedSuppressRecoveryDurationMs"),
            "DA05" to listOf("phaseAxis", "pausedExcludedDurationMs"),
            "DA06" to listOf("primaryAnalysisPartition", "eligibleUncoveredDurationMs"),
            "DA07" to listOf("deviceStateDurations", "live")
        )
        for ((id, keys) in audit) {
            val parent = listOf<Any>("trainFlowSessionExport", "sessions", 0, "heartRate", "durationAudit") +
                keys.dropLast(1)
            cross("H06", id, parent, keys.last()) {
                it[keys.last()] = (it[keys.last()] as BigDecimal) + BigDecimal.ONE
            }
        }
        cross("FORMAT-DA08", "DA08", listOf("trainFlowSessionExport", "sessions", 0,
            "heartRate", "durationAudit", "deviceReasonDurations"), "initial_acquisition") {
            it["initial_acquisition"] = BigDecimal(10_001)
        }
        val reasonKeys = listOf("sessionReasons", "phaseReasons")
        for (reasonKey in reasonKeys) {
            cross("H10", "QR15-REVERSE-$reasonKey", listOf("trainFlowSessionExport", "sessions", 0,
                "heartRate", "originalAnalysis", "qualityReasons"), reasonKey) {
                mutableArray(it[reasonKey]).reverse()
            }
            cross("H10", "QR15-DUPLICATE-$reasonKey", listOf("trainFlowSessionExport", "sessions", 0,
                "heartRate", "originalAnalysis", "qualityReasons"), reasonKey) {
                val reasons = mutableArray(it[reasonKey]); if (reasons.isNotEmpty()) reasons.add(mutableCopy(reasons.first()))
            }
        }
        val reasonCodes = listOf(
            "no_eligible_duration", "no_canonical_samples", "canonical_only_excluded",
            "eligible_uncovered_present", "insufficient_coverage", "partial_coverage",
            "unavailable_no_effective_max", "not_requested_before_recording_start",
            "strength_prepare_excluded", "paused_excluded", "user_turned_off_excluded",
            "user_opted_out_excluded", "user_disconnected_suppress_recovery_excluded",
            "process_interrupted"
        )
        val qualityPointer = listOf<Any>("trainFlowSessionExport", "sessions", 0,
            "heartRate", "originalAnalysis", "qualityReasons")
        for ((index, reason) in reasonCodes.withIndex()) {
            val source = (1..13).map { "H%02d".format(it) }.first { id ->
                val quality = obj(parse(H_SNAPSHOTS.getValue(id).qualityReasonsJson))
                arr(quality["sessionReasons"]).map(::obj).any { it["reasonCode"] == reason }
            }
            val label = "QR%02d".format(index + 1)
            cross(source, "$label-REQUIRED", qualityPointer, "sessionReasons") {
                mutableArray(it["sessionReasons"]).removeAll { row -> obj(row)["reasonCode"] == reason }
            }
            cross("H06", "$label-FORBIDDEN", qualityPointer, "sessionReasons") {
                mutableArray(it["sessionReasons"]).add(linkedMapOf(
                    "reasonCode" to reason, "durationMs" to null))
            }
            cross(source, "$label-SCOPE", qualityPointer, "phaseReasons") {
                mutableArray(it["phaseReasons"]).add(linkedMapOf(
                    "phaseSequence" to BigDecimal(999), "reasonCode" to reason,
                    "durationMs" to null))
            }
            val reasonIndex = arr(obj(parse(H_SNAPSHOTS.getValue(source).qualityReasonsJson))["sessionReasons"])
                .map(::obj).indexOfFirst { it["reasonCode"] == reason }
            cross(source, "$label-DURATION", qualityPointer + "sessionReasons" + reasonIndex, "durationMs") {
                it["durationMs"] = (it["durationMs"] as BigDecimal?)?.plus(BigDecimal.ONE) ?: BigDecimal.ONE
            }
        }
        assertTrue("V07 matrix empty", count > 0)
        println("V07_CASE_COUNT=$count")
        failedPaths.forEach { (id, path) -> println("V07_REJECT|$id|$path") }
    }

    /** The consumer receives only bytes and reads the vocabulary inside those bytes. */
    private inner class ConsumerDocument(bytes: ByteArray) {
        val envelope = root(bytes)
        val entries = arr(obj(envelope["dataDictionary"])["fields"]).map(::obj)
        val rules = arr(obj(envelope["dataDictionary"])["rules"]).map(::obj)
        val selection = obj(envelope["selection"])
        val items = arr(envelope["sessions"]).map(::obj)

        fun item(id: String): Map<String, Any?> = items.single {
            obj(it["session"])["sessionId"] == id
        }

        fun field(path: String): Map<String, Any?> = entries.first {
            it["path"] == path
        }.also {
            assertTrue("$path has no file explanation", (it["purpose"] as String).isNotBlank())
            assertTrue("$path has no provenance", (it["provenance"] as String).isNotBlank())
        }

        fun rule(id: String): String = rules.single { it["id"] == id }["description"] as String
    }

    @Test fun independentConsumerAnswersIc01Through10() = runBlocking {
        freshDatabase()
        val canonical = listOf(freeFixture(), fixtures.getValue("S"), fixtures.getValue("L"),
            fixtures.getValue("F"), fixtures.getValue("C"))
        canonical.forEach { seedFixture(it) }
        val multi = ConsumerDocument(encode(canonical.map { it.header.id }))

        val legacy = linkedMapOf<String, ConsumerDocument>()
        for ((id, mode, plan) in listOf(
            Triple("L-T", "timed", """{"title":"Legacy old","mode":"timed","blocks":[]}"""),
            Triple("L-S", "strength", """{"title":"Legacy old","mode":"strength","blocks":[]}"""),
            Triple("L-F", "follow_along", """{"title":"Legacy old","mode":"follow_along","blocks":[]}"""),
            Triple("L-FN", "follow_along", """{"title":"Legacy old","mode":"follow_along","blocks":[],"planId":null,"preferences":null,"followAlong":null}"""),
            Triple("L-FV", "follow_along", """{"title":"空 格 \"引号\" \\ 反斜杠\n换行","mode":"follow_along","blocks":[],"planId":"old-plan","preferences":{},"followAlong":{"preset":true,"coachMediaIds":[],"chapterIds":[],"timelineCueIds":[],"musicTrackIds":[]}}""")
        )) {
            freshDatabase()
            database.workoutSessionDao().insertSession(legacyHeader(id, mode, plan,
                if (id == "L-FV") "old-plan" else null))
            if (id == "L-S") seedExecution(id)
            legacy[id] = ConsumerDocument(encode(listOf(id), listOf(id)))
        }
        val h = linkedMapOf<String, ConsumerDocument>()
        for (number in 1..13) {
            val id = "H%02d".format(number)
            freshDatabase()
            seedH(id)
            h[id] = ConsumerDocument(encode(listOf(id)))
        }
        val time = linkedMapOf<String, ConsumerDocument>()
        val strength = fixtures.getValue("S")
        val dated = listOf(
            Triple("T01", "2024-02-29T15:59:59Z", "2024-02-29"),
            Triple("T02", "2025-12-31T18:14:59Z", "2025-12-31"),
            Triple("T03", strength.header.startedAt!!, "2026-09-13")
        )
        for ((id, started, date) in dated) {
            freshDatabase()
            val fixture = strength.copy(header = strength.header.copy(
                id = id, startedAt = started,
                endedAt = Instant.parse(started).plusSeconds(6).toString(),
                startLocalDate = date,
                startZoneId = when (id) { "T01" -> "Asia/Shanghai"; "T02" -> "Asia/Kathmandu"; else -> "UTC" },
                startUtcOffsetSeconds = when (id) { "T01" -> 28_800L; "T02" -> 20_700L; else -> 0L }
            ), phases = strength.phases.map { it.copy(sessionId = id, id = it.id.replace("s-S", id)) })
            seedFixture(fixture)
            time[id] = ConsumerDocument(encode(listOf(id), startDate = LocalDate.parse(date),
                endDate = LocalDate.parse(date)))
        }
        time["T04"] = h.getValue("H10")
        for ((id, mode) in listOf("T05" to "timed", "T06" to "follow_along")) {
            freshDatabase()
            val base = legacyHeader(id, mode, """{"title":"Legacy old","mode":"$mode","blocks":[]}""")
            database.workoutSessionDao().insertSession(if (id == "T05") base.copy(
                startedAt = "2026-09-07T16:00:00Z", endedAt = "2026-09-07T16:00:12Z") else base)
            time[id] = ConsumerDocument(encode(listOf(id), listOf(id)))
        }

        // IC01: stable session and phase identities, including whole-session free follow-along.
        val first = multi.item("s-F0")
        val freePhase = obj(arr(obj(first["execution"])["phases"]).single())
        assertEquals("free_session", obj(obj(freePhase["phaseIdentity"])["payload"])["variant"])
        assertEquals("跟练", obj(freePhase["display"])["label"])
        assertEquals(listOf("s-F0", "s-S", "s-L", "s-F", "s-C"),
            multi.items.map { obj(it["session"])["sessionId"] })
        assertTrue(multi.rule("PH-01").contains("机器身份"))
        multi.field("$.trainFlowSessionExport.sessions[].execution.phases[].phaseIdentity")

        // IC02: two different tuples at the same offset retain their original numbers.
        val h11 = obj(h.getValue("H11").item("H11")["heartRate"])
        val h11Points = arr(h11["samples"]).map(::obj)
        assertEquals(listOf(BigDecimal.ZERO, BigDecimal.ZERO), h11Points.take(2).map { it["offsetMs"] })
        assertEquals(listOf(BigDecimal("9007199254740993"), BigDecimal("9007199254740994")),
            h11Points.take(2).map { it["mutationSequence"] })
        assertEquals(listOf(BigDecimal(65535), BigDecimal(150)), h11Points.take(2).map { it["bpm"] })
        assertTrue(h.getValue("H11").rule("ORDER-01").contains("sampleSequence"))

        // IC03/04: plan versus actual, zero versus null, and legacy absence versus explicit null.
        val x = legacy.getValue("L-S").item("L-S")
        val sets = arr(obj(x["execution"])["strengthSetRecords"]).map(::obj)
        assertEquals(BigDecimal(200), obj(sets[0]["plannedRepTarget"])["maxReps"])
        assertEquals(BigDecimal("60.0"), obj(sets[0]["plannedWeight"])["value"])
        assertEquals(BigDecimal("62.5"), obj(sets[0]["actualWeight"])["value"])
        assertEquals(BigDecimal(9), sets[0]["actualReps"])
        assertEquals(BigDecimal.ZERO, sets[1]["actualReps"])
        assertNull(sets[2]["actualReps"])
        assertEquals(BigDecimal("0.0"), obj(sets[1]["actualWeight"])["value"])
        assertNull(sets[2]["actualWeight"])
        val absent = obj(parse(obj(legacy.getValue("L-F").item("L-F")["session"])["planSnapshotJson"] as String))
        val explicitNull = obj(parse(obj(legacy.getValue("L-FN").item("L-FN")["session"])["planSnapshotJson"] as String))
        val value = obj(parse(obj(legacy.getValue("L-FV").item("L-FV")["session"])["planSnapshotJson"] as String))
        for (key in listOf("planId", "preferences", "followAlong")) {
            assertFalse(absent.containsKey(key))
            assertTrue(explicitNull.containsKey(key))
            assertNull(explicitNull[key])
            assertNotNull(value[key])
        }
        assertTrue(legacy.getValue("L-F").rule("PL-01").contains("legacy"))

        // IC05/06: user intent and device state are separate; excluded phases keep raw.
        val h10Heart = obj(h.getValue("H10").item("H10")["heartRate"])
        val acquisitions = arr(h10Heart["intentAndAcquisition"]).map(::obj)
        assertEquals(setOf("user_turned_off", "user_opted_out", "user_disconnected_suppress_recovery"),
            acquisitions.mapNotNull { it["intentReason"] as String? }.toSet())
        assertTrue(acquisitions.any { it["recordingIntent"] == "expected_recording" && it["deviceState"] == "live" })
        assertTrue(h.getValue("H10").rule("HR-03").contains("不同轴"))
        for (id in listOf("H07", "H09")) {
            assertTrue(arr(obj(h.getValue(id).item(id)["heartRate"])["samples"]).isNotEmpty())
            assertTrue(arr(obj(h.getValue(id).item(id)["execution"])["phases"]).map(::obj)
                .any { it["phaseKind"] == "paused" })
        }
        assertTrue(arr(obj(h.getValue("H10").item("H10")["execution"])["phases"]).map(::obj)
            .any { it["phaseKind"] == "strength_prepare_set" })

        // IC07: convenience status never replaces the original independent axes.
        assertEquals("not_recorded", obj(first["heartRate"])["status"])
        for ((id, status) in listOf("H02" to "zero_samples", "H01" to "no_eligible_duration",
            "H08" to "no_eligible_duration", "H09" to "no_eligible_duration",
            "H05" to "recorded_no_zones")) {
            val heart = obj(h.getValue(id).item(id)["heartRate"])
            assertEquals(status, heart["status"])
            val analysis = obj(heart["originalAnalysis"])
            assertTrue(analysis.containsKey("sampleStatus"))
            assertTrue(analysis.containsKey("coverageStatus"))
            assertTrue(analysis.containsKey("zoneStatus"))
        }
        assertTrue(h.getValue("H05").rule("HR-02").contains("正交"))

        // IC08/09: actual selected subset and frozen origin versus derived end.
        assertEquals(listOf("s-F0", "s-S", "s-L", "s-F", "s-C"), multi.selection["includedSessionIds"])
        assertEquals("user_selected_subset", multi.selection["selectionScope"])
        assertTrue(multi.rule("SEL-01").contains("不表示那天没有训练"))
        for ((id, date, zone, offset) in listOf(
            QuadTime("T01", "2024-02-29", "Asia/Shanghai", 28_800),
            QuadTime("T02", "2025-12-31", "Asia/Kathmandu", 20_700)
        )) {
            val metadata = obj(obj(time.getValue(id).item(id)["session"])["timeMetadata"])
            assertEquals(date, metadata["startLocalDate"])
            assertEquals(zone, metadata["startZoneId"])
            assertEquals(BigDecimal(offset), metadata["startUtcOffsetSeconds"])
            assertEquals("start_anchor_plus_trusted_offset", metadata["trustedEndAtBasis"])
        }
        assertNull(obj(time.getValue("T04").item("H10")["session"])["endedAt"])
        val t05Metadata = obj(obj(time.getValue("T05").item("T05")["session"])["timeMetadata"])
        assertEquals("legacy_stored", t05Metadata["startTimestampBasis"])
        assertNull(t05Metadata["startZoneId"])
        assertTrue(time.getValue("T01").rule("TIME-02").contains("推导"))

        // IC10: original binding and four distinct thresholds are readable in the file.
        val h06 = obj(h.getValue("H06").item("H06")["heartRate"])
        val recording = obj(h06["recording"])
        val analysis = obj(h06["originalAnalysis"])
        assertEquals(recording["originalAnalysisVersion"], analysis["analysisVersion"])
        assertEquals(recording["endedMutationSequence"], analysis["inputLastMutationSequence"])
        assertEquals(BigDecimal(2500), obj(analysis["analysisConfig"])["sampleValidityCapMs"])
        val semantics = h.getValue("H06").rule("HR-04")
        assertTrue(semantics.contains("20秒"))
        assertTrue(semantics.contains("50%"))
        assertTrue(semantics.contains("80%"))
        assertTrue(semantics.contains("70%"))
        assertTrue(h.getValue("H06").rule("HR-01").contains("不得取latest或重新分析"))
    }

    private data class QuadTime(val id: String, val date: String, val zone: String, val offset: Int)

    @Test fun forwardsReadAndHistoricalFailures() = runBlocking {
        freshDatabase()
        assertStrictForwarded("R01", "absent", WorkoutSessionStrictReadResult.NotFound)

        val base = fixtures.getValue("L")
        val running = base.copy(
            header = base.header.copy(status = "active", endedAt = null, trustedEndOffsetMs = null,
                terminalReason = null),
            phases = base.phases.dropLast(1) + base.phases.last().copy(
                endOffsetMs = null, endMutationSequence = null, openMarker = 1
            )
        )
        freshDatabase()
        seedFixture(running)
        val nonterminal = WorkoutSessionRepository(database).readSessionStrict(running.header.id)
        assertTrue(nonterminal.toString(), nonterminal is WorkoutSessionStrictReadResult.Nonterminal)
        assertStrictForwarded("R02", running.header.id, nonterminal)

        val invalid = listOf(
            "R03" to base.copy(header = base.header.copy(timelineVersion = 2)),
            "R04" to base.copy(header = base.header.copy(displayMetadataContractVersion = 2)),
            "R05" to base.copy(phases = base.phases.mapIndexed { index, phase ->
                if (index == 0) phase.copy(phaseIdentityJson = phase.phaseIdentityJson.replace(
                    "\"family\":\"legacy_timed_v1\"", "\"family\":\"__unsupported__\"")) else phase
            }),
            "R06" to base.copy(phases = base.phases.mapIndexed { index, phase ->
                if (index == 0) phase.copy(phaseIdentityJson = phase.phaseIdentityJson.replace(
                    "\"variant\":\"boundary_block_work\",", "")) else phase
            }),
            "R07" to base.copy(phases = base.phases.mapIndexed { index, phase ->
                if (index == 0) phase.copy(phaseIdentityJson = phase.phaseIdentityJson.replace(
                    "\"mode\":\"timed\"", "\"mode\":\"strength\"")) else phase
            }),
            "R08" to base.copy(phases = base.phases.mapIndexed { index, phase ->
                if (index == 0) phase.copy(phaseIdentityJson = phase.phaseIdentityJson.replace(
                    "\"blockId\":\"w\"", "\"blockId\":\"missing\"")) else phase
            })
        )
        for ((id, fixture) in invalid) {
            freshDatabase()
            seedFixture(fixture)
            val result = WorkoutSessionRepository(database).readSessionStrict(fixture.header.id)
            assertTrue("$id $result", result is WorkoutSessionStrictReadResult.Unavailable)
            assertStrictForwarded(id, fixture.header.id, result)
        }
        freshDatabase()
        val first = freeFixture()
        seedFixture(first)
        val second = invalid.first { it.first == "R05" }.second
        seedFixture(second)
        val repository = WorkoutSessionRepository(database)
        val selection = WorkoutSessionExportSelection("calendar", null, null, null, null,
            listOf(first.header.id, second.header.id), emptyList())
        val output = StringWriter()
        val encoder = WorkoutSessionExport(output, selection, GENERATED_AT, "zh-CN")
        encoder.writeSession(repository.readSessionStrict(first.header.id))
        val failingRead = repository.readSessionStrict(second.header.id)
        val rejected = assertThrows(WorkoutSessionExportReadRejected::class.java) {
            encoder.writeSession(failingRead)
        }
        assertSame(failingRead, rejected.source)
        assertEquals(second.header.id, rejected.requestedSessionId)
        assertThrows(IllegalStateException::class.java) { encoder.finish() }

        freshDatabase()
        val legacy = legacyHeader("R11", "timed", """{"title":"Legacy old","mode":"timed","blocks":[]}""")
        database.workoutSessionDao().insertSession(legacy)
        database.canonicalTimelineHeartRateDao().insertRecording(HeartRateRecordingEntity(
            "R11-recording", legacy.id, "terminal", 0, 0, 1, 1,
            sourceContractVersion = 1, sourceKind = "ble_hrs", acquisitionContractVersion = 1,
            parameterSnapshotVersion = 1
        ))
        val r11 = WorkoutSessionRepository(database).readSessionStrict(legacy.id)
        assertTrue(r11.toString(), r11 is WorkoutSessionStrictReadResult.Unavailable)
        assertStrictForwarded("R11", legacy.id, r11)

        for ((id, literal) in listOf("R12" to "weight=NaN,kg", "R13" to "weight=Infinity,kg")) {
            freshDatabase()
            val header = legacyHeader(id, "strength", """{"title":"Legacy old","mode":"strength","blocks":[]}""")
            database.workoutSessionDao().insertSession(header)
            database.workoutSessionDao().upsertStrengthSetRecords(listOf(StrengthSetRecordEntity(
                "bad-weight", id, "exercise", null, 0, "working", actualJson = literal
            )))
            val result = WorkoutSessionRepository(database).readSessionStrict(id)
            assertTrue("$id $result", result is WorkoutSessionStrictReadResult.Unavailable)
            assertStrictForwarded(id, id, result)
        }

        freshDatabase()
        val overflow = fixtures.getValue("O")
        seedFixture(overflow)
        val read = WorkoutSessionRepository(database).readSessionStrict(overflow.header.id)
        assertTrue(read.toString(), read is WorkoutSessionStrictReadResult.CanonicalTerminal)
        val error = assertThrows(WorkoutSessionExportHistoricalRejected::class.java) {
            WorkoutSessionExport(StringWriter(), WorkoutSessionExportSelection("single_session", null, null,
                null, null, listOf(overflow.header.id), emptyList()), GENERATED_AT, "zh-CN").writeSession(read)
        }
        assertEquals(overflow.header.id, error.requestedSessionId)
        assertTrue(error.source is WorkoutSessionHistoricalResult.InvalidPlannedDuration)

        freshDatabase()
        val time = fixtures.getValue("S").let { it.copy(header = it.header.copy(startZoneId = null)) }
        seedFixture(time)
        val r15 = WorkoutSessionRepository(database).readSessionStrict(time.header.id)
        assertTrue(r15.toString(), r15 is WorkoutSessionStrictReadResult.Unavailable)
        assertStrictForwarded("R15", time.header.id, r15)
        // R09/R10 use the H06 persisted fixture in this same fixed method.
        forwardAnalysisFailures()
    }

    private fun assertStrictForwarded(id: String, requestedId: String, source: WorkoutSessionStrictReadResult) {
        val output = StringWriter()
        val encoder = WorkoutSessionExport(output, WorkoutSessionExportSelection(
            "single_session", null, null, null, null, listOf(requestedId), emptyList()
        ), GENERATED_AT, "zh-CN")
        val error = assertThrows(id, WorkoutSessionExportReadRejected::class.java) { encoder.writeSession(source) }
        assertSame(source, error.source)
        assertEquals(requestedId, error.requestedSessionId)
    }

    private suspend fun forwardAnalysisFailures() {
        freshDatabase()
        seedH("H06")
        database.openHelper.writableDatabase.execSQL(
            "DELETE FROM heart_rate_analysis_snapshots WHERE recording_id='H06-r'"
        )
        val missing = WorkoutSessionRepository(database).readSessionStrict("H06")
        assertTrue(missing.toString(), missing is WorkoutSessionStrictReadResult.Unavailable)
        assertStrictForwarded("R09", "H06", missing)

        freshDatabase()
        seedH("H06")
        database.openHelper.writableDatabase.execSQL(
            "UPDATE heart_rate_analysis_snapshots SET input_last_mutation_sequence=99 WHERE recording_id='H06-r'"
        )
        val mismatch = WorkoutSessionRepository(database).readSessionStrict("H06")
        assertTrue(mismatch.toString(), mismatch is WorkoutSessionStrictReadResult.Unavailable)
        assertStrictForwarded("R10", "H06", mismatch)
    }

    @Test fun preservesPersistedHeartRateAxesAndAnalysis() = runBlocking {
        val statuses = mapOf(
            "H01" to "no_eligible_duration", "H02" to "zero_samples", "H03" to "insufficient",
            "H04" to "partial", "H05" to "recorded_no_zones", "H06" to "recorded",
            "H07" to "insufficient", "H08" to "no_eligible_duration", "H09" to "no_eligible_duration",
            "H10" to "zero_samples", "H11" to "recorded_no_zones", "H12" to "partial",
            "H13" to "recorded"
        )
        for ((id, expectedStatus) in statuses) {
            freshDatabase()
            val input = seedH(id)
            val strict = WorkoutSessionRepository(database).readSessionStrict(id)
            assertTrue("$id $strict", strict is WorkoutSessionStrictReadResult.CanonicalTerminal)
            strict as WorkoutSessionStrictReadResult.CanonicalTerminal
            assertEquals("$id original snapshot", H_SNAPSHOTS.getValue(id), strict.graph.snapshots.single())
            val bytes = encode(listOf(id))
            assertEquals(parse(goldenDocument(listOf(id))), parse(bytes))
            val heart = obj(obj(sessions(bytes).single())["heartRate"])
            assertEquals(id, expectedStatus, heart["status"])
            val original = obj(heart["originalAnalysis"])
            val snapshot = H_SNAPSHOTS.getValue(id)
            assertEquals(expectedStatus, original["status"])
            assertEquals(snapshot.sampleStatus, original["sampleStatus"])
            assertEquals(snapshot.coverageStatus, original["coverageStatus"])
            assertEquals(snapshot.zoneStatus, original["zoneStatus"])
            assertEquals(BigDecimal(snapshot.canonicalSampleCount), original["canonicalSampleCount"])
            assertEquals(BigDecimal(snapshot.primaryPointSampleCount), original["primaryPointSampleCount"])
            assertEquals(parse(snapshot.analysisConfigJson), original["analysisConfig"])
            assertEquals(parse(snapshot.phaseAggregatesJson), original["phaseAggregates"])
            assertEquals(parse(snapshot.qualityReasonsJson), original["qualityReasons"])
            assertEquals(parse(snapshot.durationBreakdownJson), heart["durationAudit"])
            val raw = arr(heart["samples"])
            assertEquals(input.samples.size, raw.size)
            val sorted = input.samples.sortedWith(compareBy<HSample> { it.offset }.thenBy { it.mutation }.thenBy { it.sequence })
            sorted.forEachIndexed { index, sample ->
                val point = obj(raw[index])
                assertEquals(BigDecimal(sample.offset), point["offsetMs"])
                assertEquals(BigDecimal(sample.mutation), point["mutationSequence"])
                assertEquals(BigDecimal(sample.sequence), point["sampleSequence"])
                assertEquals(BigDecimal(sample.bpm), point["bpm"])
            }
            emitCase(id, bytes)
        }
    }

    @Test fun preservesExactNumbersAndUtf8() { runBlocking {
        freshDatabase()
        seedH("H11")
        val h11 = encode(listOf("H11"))
        val heart = obj(obj(sessions(h11).single())["heartRate"])
        val samples = arr(heart["samples"]).map(::obj)
        val n = BigDecimal("9007199254740992")
        assertEquals(listOf(n + BigDecimal.ONE, n + BigDecimal(2), n + BigDecimal(3)),
            samples.map { it["mutationSequence"] })
        assertEquals(listOf(BigDecimal(65_535), BigDecimal(150), BigDecimal(130)), samples.map { it["bpm"] })
        assertEquals(n + BigDecimal.ONE, obj(heart["originalAnalysis"])["highestMutationSequence"])
        val rounded = BigDecimal((9_007_199_254_740_993L).toDouble().toLong())
        val h11Golden = goldenDocument(listOf("H11"))
        val analysisPointer = listOf<Any>("trainFlowSessionExport", "sessions", 0, "heartRate", "originalAnalysis")
        println("NUM01|" + fixedMutation("NUM01", h11, h11Golden, analysisPointer, "highestMutationSequence") {
            it["highestMutationSequence"] = rounded
        })

        freshDatabase()
        val strength = legacyHeader("L-S", "strength", """{"title":"Legacy old","mode":"strength","blocks":[]}""")
        database.workoutSessionDao().insertSession(strength)
        seedExecution(strength.id)
        val x = encode(listOf(strength.id), listOf(strength.id))
        val sets = arr(obj(obj(sessions(x).single())["execution"])["strengthSetRecords"]).map(::obj)
        assertEquals(BigDecimal.ZERO, sets[1]["actualReps"])
        assertNull(sets[2]["actualReps"])
        val xGolden = goldenDocument(listOf("L-S"), listOf("L-S"))
        val setsPointer = listOf<Any>("trainFlowSessionExport", "sessions", 0, "execution", "strengthSetRecords")
        println("NUM02|" + fixedMutation("NUM02", x, xGolden, setsPointer + 1, "actualReps") {
            it["actualReps"] = null
        })
        assertEquals("lb", obj(sets[0]["actualWeight"])["unit"])
        assertEquals("kg", obj(sets[1]["actualWeight"])["unit"])
        assertEquals(BigDecimal("62.5"), obj(sets[0]["actualWeight"])["value"])
        println("NUM03|" + fixedMutation("NUM03", x, xGolden, setsPointer + 0 + "actualWeight", "unit") {
            it["unit"] = "__unsupported__"
        })

        freshDatabase()
        val fv = legacyHeader("L-FV", "follow_along", """{"title":"空 格 \"引号\" \\ 反斜杠\n换行","mode":"follow_along","blocks":[],"planId":"old-plan","preferences":{},"followAlong":{"preset":true,"coachMediaIds":[],"chapterIds":[],"timelineCueIds":[],"musicTrackIds":[]}}""", "old-plan")
        database.workoutSessionDao().insertSession(fv)
        val fvBytes = encode(listOf(fv.id), listOf(fv.id))
        assertFalse(fvBytes.take(3) == listOf(0xEF.toByte(), 0xBB.toByte(), 0xBF.toByte()))
        assertArrayEquals(fv.planSnapshotJson.toByteArray(Charsets.UTF_8),
            (obj(obj(sessions(fvBytes).single())["session"])["planSnapshotJson"] as String).toByteArray(Charsets.UTF_8))
        for (literal in listOf("{\"value\":NaN}", "{\"value\":Infinity}")) {
            assertThrows("NUM04", Exception::class.java) { parse(literal) }
        }
        println("NUM05-duration|" + fixedMutation("NUM05-duration", h11, h11Golden, analysisPointer, "eligibleDurationMs") {
            it["eligibleDurationMs"] = BigDecimal("0.5")
        })
        val samplePointer = listOf<Any>("trainFlowSessionExport", "sessions", 0, "heartRate", "samples", 0)
        println("NUM05-sequence|" + fixedMutation("NUM05-sequence", h11, h11Golden, samplePointer, "mutationSequence") {
            it["mutationSequence"] = BigDecimal("0.5")
        })
        val indexPointer = listOf<Any>("trainFlowSessionExport", "sessions", 0, "execution", "timedRestExtensions", 0)
        println("NUM05-index|" + fixedMutation("NUM05-index", x, xGolden, indexPointer, "stepIndex0") {
            it["stepIndex0"] = BigDecimal("0.5")
        })
        println("NUM06-Long|" + fixedMutation("NUM06-Long", h11, h11Golden, samplePointer, "mutationSequence") {
            it["mutationSequence"] = BigDecimal("9223372036854775808")
        })

        freshDatabase()
        val max = fixtures.getValue("S").let { fixture -> fixture.copy(header = fixture.header.copy(
            id = "NUM06-Instant", status = "abandoned", terminalReason = "process_interrupted",
            startedAt = "+1000000000-12-31T23:59:59.999999999Z", endedAt = null,
            startLocalDate = null, startZoneId = null, startUtcOffsetSeconds = null,
            timeMetadataSourceContractVersion = null
        ), phases = fixture.phases.map { it.copy(sessionId = "NUM06-Instant", id = it.id.replace("s-S", "NUM06-Instant")) }) }
        seedFixture(max)
        val strict = WorkoutSessionRepository(database).readSessionStrict(max.header.id)
        if (strict is WorkoutSessionStrictReadResult.CanonicalTerminal) {
            assertThrows("NUM06-Instant", DateTimeException::class.java) {
                WorkoutSessionExport(StringWriter(), WorkoutSessionExportSelection("single_session", null, null,
                    null, null, listOf(max.header.id), listOf(max.header.id)), GENERATED_AT, "zh-CN")
                    .writeSession(strict)
            }
        } else {
            assertTrue("NUM06-Instant strict boundary: $strict", strict is WorkoutSessionStrictReadResult.Unavailable)
        }
    } }

    private data class HPhase(val kind: String, val start: Long, val end: Long,
        val firstMutation: Long, val lastMutation: Long)
    private data class HAcquisition(val start: Long, val end: Long, val firstMutation: Long,
        val lastMutation: Long, val intent: String, val reason: String?, val device: String)
    private data class HSample(val offset: Long, val mutation: Long, val sequence: Long, val bpm: Int)
    private data class HInput(val end: Long, val terminalMutation: Long, val recordingStart: Long,
        val recordingStartMutation: Long, val phases: List<HPhase>,
        val acquisitions: List<HAcquisition>, val samples: List<HSample>,
        val effectiveMax: Int? = null, val interrupted: Boolean = false)

    private fun hInput(id: String): HInput {
        fun sample(offset: Long, sequence: Long, bpm: Int) = HSample(offset, sequence, sequence, bpm)
        fun standard(samples: List<HSample>, max: Int? = null, paused: Boolean = false,
            excluded: Boolean = false): HInput = HInput(
            10_000L, 100L, 0L, 0L,
            listOf(HPhase(if (paused) "paused" else "strength_active_set", 0L, 10_000L, 0L, 100L)),
            listOf(HAcquisition(0L, 10_000L, 0L, 100L,
                if (excluded) "user_excluded" else "expected_recording",
                if (excluded) "user_turned_off" else null,
                if (excluded) "not_observing" else "live")),
            samples, max
        )
        return when (id) {
            "H01" -> standard(emptyList(), paused = true)
            "H02" -> standard(emptyList())
            "H03" -> standard(listOf(sample(0, 1, 120)))
            "H04" -> standard(listOf(sample(0, 1, 120), sample(2500, 2, 120)))
            "H05" -> standard(listOf(sample(0, 1, 120), sample(2500, 2, 120),
                sample(5000, 3, 120), sample(7500, 4, 120)))
            "H06" -> standard(listOf(sample(0, 1, 120), sample(2500, 2, 120),
                sample(5000, 3, 120), sample(7500, 4, 120)), max = 200)
            "H07" -> HInput(10_000L, 100L, 0L, 0L,
                listOf(HPhase("paused", 0, 1000, 0, 2),
                    HPhase("strength_active_set", 1000, 10_000, 2, 100)),
                listOf(HAcquisition(0, 10_000, 0, 100, "expected_recording", null, "live")),
                listOf(sample(0, 1, 120)))
            "H08" -> standard(emptyList(), excluded = true)
            "H09" -> standard(listOf(sample(0, 1, 120)), paused = true)
            "H10" -> HInput(6000L, 100L, 500L, 1L,
                listOf(HPhase("strength_active_set", 0, 1000, 0, 2),
                    HPhase("strength_prepare_set", 1000, 2000, 2, 3),
                    HPhase("paused", 2000, 3000, 3, 4),
                    HPhase("strength_active_set", 3000, 6000, 4, 100)),
                listOf(HAcquisition(500, 3000, 1, 4, "expected_recording", null, "live"),
                    HAcquisition(3000, 3500, 4, 5, "user_excluded", "user_turned_off", "not_observing"),
                    HAcquisition(3500, 4000, 5, 6, "user_excluded", "user_opted_out", "not_observing"),
                    HAcquisition(4000, 4500, 6, 7, "user_excluded", "user_disconnected_suppress_recovery", "not_observing"),
                    HAcquisition(4500, 6000, 7, 100, "expected_recording", null, "live")),
                emptyList(), interrupted = true)
            "H11" -> {
                val n = 9_007_199_254_740_992L
                HInput(1000L, n + 4, 0L, n,
                    listOf(HPhase("strength_active_set", 0, 1000, n, n + 4)),
                    listOf(HAcquisition(0, 1000, n, n + 4, "expected_recording", null, "live")),
                    listOf(HSample(0, n + 1, n + 1, 65_535), HSample(0, n + 2, n + 2, 150),
                        HSample(500, n + 3, n + 3, 130)))
            }
            "H12" -> standard(listOf(sample(0, 1, 120), sample(2500, 2, 120), sample(4500, 3, 120)))
            "H13" -> standard(listOf(sample(0, 1, 120), sample(2500, 2, 120),
                sample(5000, 3, 120), sample(5500, 4, 120)), max = 200)
            else -> error(id)
        }
    }

    private suspend fun seedH(id: String): HInput {
        val input = hInput(id)
        val strength = fixtures.getValue("S")
        val start = Instant.parse("2026-09-29T00:00:00Z")
        val header = strength.header.copy(
            id = id, startedAt = start.toString(),
            endedAt = if (input.interrupted) null else start.plusMillis(input.end).toString(),
            status = if (input.interrupted) "abandoned" else "completed",
            totalElapsedSec = (input.end / 1000).toInt(),
            effectiveElapsedSec = (input.end / 1000).toInt(), pausedElapsedSec = 0,
            lastDurableOffsetMs = input.end, lastMutationSequence = input.terminalMutation,
            trustedEndOffsetMs = input.end,
            terminalReason = if (input.interrupted) "process_interrupted" else "completed",
            startLocalDate = "2026-09-29", startZoneId = "UTC", startUtcOffsetSeconds = 0L,
            timeMetadataSourceContractVersion = 1L
        )
        database.workoutSessionDao().insertSession(header)
        val dao = database.canonicalTimelineHeartRateDao()
        val templateByKind = mapOf(
            "strength_prepare_set" to strength.phases[0].phaseIdentityJson,
            "strength_active_set" to strength.phases[1].phaseIdentityJson,
            "paused" to strength.phases[4].phaseIdentityJson
        )
        input.phases.mapIndexed { sequence, phase ->
            val identity = templateByKind.getValue(phase.kind)
                .replace("\"actualExerciseId\":\"ex-sa\"", "\"actualExerciseId\":\"ex-sp\"")
                .replace("\"substitutedFromExerciseId\":\"ex-sp\"", "\"substitutedFromExerciseId\":null")
            WorkoutPhaseIntervalEntity("$id-p-$sequence", id, sequence, phase.start, phase.end,
                phase.firstMutation, phase.lastMutation, null, phase.kind, identity)
        }.reversed().forEach { dao.insertPhaseInterval(it) }
        val recordingId = "$id-r"
        dao.insertRecording(HeartRateRecordingEntity(
            recordingId, id, "terminal", input.recordingStart, input.recordingStartMutation,
            input.end, input.terminalMutation, 1, "ble_hrs", 1, 1,
            personalMaxBpm = input.effectiveMax, effectiveMaxBpm = input.effectiveMax,
            effectiveMaxSource = if (input.effectiveMax == null) null else "personal_max",
            zoneSnapshotJson = if (input.effectiveMax == null) null else ZONE_SNAPSHOT_200,
            originalAnalysisVersion = 1
        ))
        input.acquisitions.mapIndexed { sequence, acq -> HeartRateAcquisitionIntervalEntity(
            "$id-a-$sequence", recordingId, sequence, acq.start, acq.end,
            acq.firstMutation, acq.lastMutation, null, acq.intent, acq.reason, acq.device, null
        ) }.reversed().forEach { dao.insertAcquisitionInterval(it) }
        input.samples.reversed().forEach { sample -> dao.insertSample(HeartRateSampleEntity(
            recordingId, sample.sequence, sample.offset, sample.mutation, sample.bpm
        )) }
        dao.insertAnalysisSnapshot(H_SNAPSHOTS.getValue(id).copy(recordingId = recordingId))
        return input
    }

