    "tSessionEntity及validated planRoot\",\"purpose\":\"canonical最后可信终点，相对session单调时间锚点\",\"condition\":\"父对象存在且非null\",\"presence\":\"required_nullable\",\"nullMeaning\":\"legacy没有可信canonical相对终点\",\"enumValues\":[],\"relations\":[\"相关规则：GEN-01、GEN-02、SEL-01\"]}\n],\n\"rules\":[\n{\"id\":\"ACQ-01\",\"description\":\"recordingIntent=expected_recording时intentReason=null；user_excluded时intentReason必须为user_turned_off/user_opted_out/user_disconnected_suppress_recovery之一。deviceReason可null，非null须匹配deviceState：not_observing/live无非null值；no_source_selected→source_not_selected；permission_required→permission_missing/permission_revoked；bluetooth_unavailable→bluetooth_off/platform_unavailable；searching/connecting/waiting_first_sample→initial_acquisition/automatic_recovery；stale→first_sample_timeout/sample_stale_timeout；reconnecting→automatic_recovery/unexpected_disconnect；disconnected→source_unavailable/unexpected_disconnect/connection_timeout；technical_failure→measurement_stream_unavailable/platform_failure。字典词汇不表示当前已交付每一种设备机制。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.intentAndAcquisition[]\"]},\n{\"id\":\"DA01\",\"description\":\"canonicalSessionDurationMs = notRequestedBeforeRecordingStartMs + intentAxis.userExcludedDurationMs + phaseAxis.phaseExcludedDurationMs + phaseAxis.primaryEligibleDurationMs\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.durationAudit\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\"]},\n{\"id\":\"DA02\",\"description\":\"recordingWindowDurationMs = canonicalSessionDurationMs - notRequestedBeforeRecordingStartMs\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.durationAudit\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\"]},\n{\"id\":\"DA03\",\"description\":\"intentAxis.expectedRecordingDurationMs + intentAxis.userExcludedDurationMs = recordingWindowDurationMs\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.durationAudit\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\"]},\n{\"id\":\"DA04\",\"description\":\"intentAxis.userExcludedDurationMs = intentAxis.userTurnedOffDurationMs + intentAxis.userOptedOutDurationMs + intentAxis.userDisconnectedSuppressRecoveryDurationMs\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.durationAudit\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\"]},\n{\"id\":\"DA05\",\"description\":\"phaseAxis.phaseExcludedDurationMs = phaseAxis.strengthPrepareExcludedDurationMs + phaseAxis.pausedExcludedDurationMs\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.durationAudit\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\"]},\n{\"id\":\"DA06\",\"description\":\"primaryAnalysisPartition.primaryEligibleDurationMs = primaryAnalysisPartition.eligibleCoveredDurationMs + primaryAnalysisPartition.eligibleUncoveredDurationMs；其eligible与phaseAxis.primaryEligibleDurationMs及originalAnalysis.eligibleDurationMs相同，covered等于originalAnalysis.coveredDurationMs\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.durationAudit\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\"]},\n{\"id\":\"DA07\",\"description\":\"sum(deviceStateDurations全部12键) = recordingWindowDurationMs；未出现的状态仍显式0\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.durationAudit\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\"]},\n{\"id\":\"DA08\",\"description\":\"sum(deviceReasonDurations全部14键) <= recordingWindowDurationMs；未出现仍0，deviceReason=null的区间不占reason项\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.durationAudit\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\"]},\n{\"id\":\"DA09\",\"description\":\"上述主要分区互斥；device state/reason是独立轴，不能与主要分区相加，不能把两设备轴互相累加成总时长\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.durationAudit\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\"]},\n{\"id\":\"DISPLAY-01\",\"description\":\"每phase有displayContractVersion=1、locale等于根displayLocale、resolutionStatus和label。通常使用既有冻结历史解析：所需entry/名称字段缺失→unresolved_missing_metadata；字段存在但空字符串→unre",
    "solved_invalid_metadata；非空（包括空白字符串）→resolved并原样保留label，不trim/翻译/加后缀或改用其他名称；所有unresolved状态label=null。free_session仅在导出内部取冻结snapshot.title给出resolved整场名称，不代表动作/阶段。legacy无canonical phases，不把旧step hint升级为phase。格式保留unresolved_invalid_identity/unsupported_identity_version词汇，但当前strict读取拒绝坏identity/未知版本，不开放损坏输入以制造成功输出。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].execution.phases[].display\",\"\$.trainFlowSessionExport.sessions[].session.planSnapshotJson::json.title\",\"\$.trainFlowSessionExport.displayLocale\"]},\n{\"id\":\"GEN-01\",\"description\":\"本文件所有对象为closed shape：实际条件下只允许fields所列键；所有祖先必须存在且非null才应用子字段说明。condition中union条件不成立的专属键禁止出现。数组原顺序有意义；对象成员文本顺序不影响解释。整数是精确十进制整数，64位整数不能经IEEE754 Double往返；有限小数用于重量等原合同允许处。所有ms、sec、bp和索引单位按字段分别解释，0是已知零，null与合法省略不等同于0。type描述非null值，null行为以presence/nullMeaning为准。\",\"relatedPaths\":[\"\$.trainFlowSessionExport\",\"\$.trainFlowSessionExport.dataDictionary\"]},\n{\"id\":\"GEN-02\",\"description\":\"exportContractVersion=2、displayContractVersion=1、dictionaryContractVersion=1独立；session的planSnapshotStorageContractVersion、timelineVersion、phaseIdentityContractVersion、payloadVersion和originalAnalysis.analysisVersion各自指其对象协议，不是数据库版本。未知/损坏/不匹配输入整份失败，不能默认补值、降级legacy或跳过一场。\",\"relatedPaths\":[\"\$.trainFlowSessionExport\",\"\$.trainFlowSessionExport.sessions[]\"]},\n{\"id\":\"GEN-03\",\"description\":\"文件含训练名称、时间、计划、实际输入和原始心率，适用于用户选择向外部工具解释。没有设备MAC/地址/GATT/provider内部诊断/notes。嵌套计划里合法旧媒体或AI profile ID仅是当时引用，不能由ID推断文件含媒体内容、内置AI、可下载资源或临床结论。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].session.planSnapshotJson::json\",\"\$.trainFlowSessionExport.sessions[].heartRate\",\"\$.trainFlowSessionExport.sessions[].execution\"]},\n{\"id\":\"HR-01\",\"description\":\"heartRate始终存在。无recording时status=not_recorded、recording/originalAnalysis/durationAudit为null、intentAndAcquisition/samples为空；有recording须terminal且原analysis绑定完整。legacy+noHR、canonical+noHR、canonical+recording合法；legacy+recording失败。原snapshot按recording.originalAnalysisVersion及同recordingId绑定，inputLastMutationSequence等于recording.endedMutationSequence；不得取latest或重新分析。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate\"]},\n{\"id\":\"HR-02\",\"description\":\"status依次投影：无recording→not_recorded；非法绑定→失败；eligibleDurationMs=0→no_eligible_duration；canonicalSampleCount=0→zero_samples；coverageStatus=insufficient/partial→同名；normal且zoneStatus=unavailable_no_effective_max→recorded_no_zones；normal且available→recorded。该便利状态不取代sampleStatus/coverageStatus/zoneStatus三个正交事实；eligible=0且无样本仍为no_eligible_duration，原no_canonical_samples原因照保留。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.status\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\"]},\n{\"id\":\"HR-03\",\"description\":\"主要统计要求用户意图expected_recording且phase属于主要适用类别；strength_prepare_set与paused排除，raw仍保留。设备断流与用户关闭/选择不记录/主动断开抑制恢复是不同轴，不把设备失败算成用户排除。canonicalSampleCount为全部raw点，primaryPointSampleCount为eligible分区raw点；sampleStatus分别是全零no_canonical_samples、有raw但主要点零canonical_only_excluded、有主要点primary_points_available。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.intentAndAcquisition[]\",\"\$.trainFlowSessionExport.sessions[].heartRate.samples[]\",\"\$.trainFlowSessionExport.sessions[].execution.phases[]\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\"]},\n{\"id\":\"HR-04\",\"description\":\"analysisConfig.sampleValidityCapMs=2500用于样本统计有效区间的上限，并受后继样本/适用区间边界限制；20秒是显示曲线断线阈值，不能用来填补统计覆盖或删除raw。coverageBasisPoints=floor(coveredDurationMs*10000/eligibleDurationMs)，eligible=0时null；阈值用精确整数交叉相乘，<50% insufficient、[50%,80%) partial、>=80% normal。phase conclusionEligible须eligible>0且达到70%，不由已舍入显示百分比决定；显示百分比=floor(bp/100)。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis.analysisConfig\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis.phaseAggregates\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis.coverageBasisPoints\"]},\n{\"id\":\"HR-05\",\"description\":\"weightedBpmMs是原整数时间积分，covered=0时weighted/observedAvg均null，否则平均按正数half-up舍入。最高点从eligible canonical原点取最大bpm，同值取最早tuple；observedMaxBpm/highestOf",
    "fsetMs/highestMutationSequence/highestSampleSequence四项同时null或引用同一点。有点但零覆盖仍可能有最高点，不能从平均null推断无raw。BLE bpm结构合法域1..65535，参数有效范围30..260不用于clamp原点，也不代表医疗可靠性。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\",\"\$.trainFlowSessionExport.sessions[].heartRate.samples[]\"]},\n{\"id\":\"HR-06\",\"description\":\"zoneSnapshot固定六项依次below_50:[无下界,5000)、from_50_to_60:[5000,6000)、from_60_to_70:[6000,7000)、from_70_to_80:[7000,8000)、from_80_to_90:[8000,9000)、at_or_above_90:[9000,无上界)，单位为相对effectiveMax的bp，边界用精确交叉相乘。snapshot effectiveMax/source与recording一致，alert不是第七区间。zoneDurations仅在zone available且eligible>0时为对象，六时长之和=coveredDurationMs；其他情况null，不把未知zone当0。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.recording.zoneSnapshot\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis.zoneDurations\"]},\n{\"id\":\"HR-07\",\"description\":\"phaseAggregates只含primary-eligible phases，按phaseSequence唯一升序且引用同场真实closed phase，不给excluded phase伪aggregate；没有per-phase zones。每phase eligible/covered/weighted积分和分别等于whole对应量（零覆盖null按无积分贡献解释）；highest tuple必须在本phase。whole max等于所有合法phase max最大值，同值取最早canonical tuple。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis.phaseAggregates\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\",\"\$.trainFlowSessionExport.sessions[].execution.phases[]\"]},\n{\"id\":\"ORDER-01\",\"description\":\"canonical边界以(offsetMs,mutationSequence)字典序定位，区间起点包含、终点排除；raw样本以(offsetMs,mutationSequence,sampleSequence)升序保留，同毫秒可以有多点且不去重/平均/抽稀。phase和acquisition按各自sequence；phase最高点引用须落在对应区间。所有数据已按同一个strict单场一致读取cut获得。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].execution.phases[]\",\"\$.trainFlowSessionExport.sessions[].heartRate.intentAndAcquisition[]\",\"\$.trainFlowSessionExport.sessions[].heartRate.samples[]\"]},\n{\"id\":\"ORDER-02\",\"description\":\"sessionStepRecords按解析后的startedAt instant再stepId升序；timedRestExtensions按eventElapsedSec、stepIndex0、cumulativeExtraRestSec、recordId升序；strengthSetRecords按setOrder、recordId升序，setOrder可为0。stepIndex0/roundIndex0为零起始，旧extension.roundIndex1为一起始；不加1改写，不把索引当stable ID。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].execution\"]},\n{\"id\":\"PH-01\",\"description\":\"phaseIdentity的family/payloadVersion/结构签名/机器身份均取原持久化值。timed_composition_v2的payloadVersion=2，其他三family的payloadVersion=1；四family为legacy_timed_v1/timed_composition_v2/strength_v1/follow_along_v1，其phaseKind及所有payload键的required/null/固定值条件逐fields entry解释。原plan中block/item/group/target/set ID与相应位置绑定，不能用名称或compatibility字段替代。结构签名与本场冻结结构相同；roundIndex0为块内轮次，stepIndex0是原展开位置；compositionVersion=2独立于payloadVersion。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].execution.phases[].phaseIdentity\",\"\$.trainFlowSessionExport.sessions[].session.planSnapshotJson::json\"]},\n{\"id\":\"PH-02\",\"description\":\"timed_composition_v2 synthetic warmup/cooldown/between_round_rest的stageGroupId等于timelineStageId，targetId等于timelineStageId加:target，targetIndex0=0；真实stage_group_*引用冻结stageGroup/target与各索引，stageInstanceIndex0/targetInstanceIndex0保持原展开序列。paused保持compositionVersion=2但其余位置键显式null。其他family paused位置键也显式null。旧力量substitutedFromExerciseId只解释历史事实，当前开始后禁止替换；跳过与实际0/未填写分别保留。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].execution.phases[].phaseIdentity\",\"\$.trainFlowSessionExport.sessions[].execution.strengthSetRecords[]\",\"\$.trainFlowSessionExport.sessions[].session.planSnapshotJson::json\"]},\n{\"id\":\"PL-01\",\"description\":\"planSnapshotJson是原持久化文本；外层JSON字符串解码后内容不变，不按当前计划/动作库补名、不重排或补key。::json入口没有planSnapshotStorageContractVersion时为legacy_unversioned；有该键时仅支持canonical storage v1且固定1，禁止把未知版本解释为legacy。canonical root的planId/preferences/followAlong必有可null；legacy这三项可省略或null，其他optional_non_null出现时仍禁止null。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].session.planSnapshotJson::json\",\"\$.trainFlowSessionExport.sessions[].session.planSnapshotJson\"]},\n{\"id\":\"PL-02\",\"description\":\"