on.phases[]\"]},\n{\"id\":\"QR13\",\"description\":\"user_disconnected_suppress_recovery_excluded：session项存在当且仅当userDisconnectedSuppressRecoveryDurationMs>0；phase项存在当且仅当phase与同类intent acquisition区间交集>0；durationMs=whole同名值或该phase对应交集时长。条件不成立禁止出现，不是可选诊断。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis.qualityReasons\",\"\$.trainFlowSessionExport.sessions[].heartRate.durationAudit\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\",\"\$.trainFlowSessionExport.sessions[].execution.phases[]\"]},\n{\"id\":\"QR14\",\"description\":\"process_interrupted：session项存在当且仅当session.terminalReason=process_interrupted；phase项禁止；durationMs=null。条件不成立禁止出现，不是可选诊断。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis.qualityReasons\",\"\$.trainFlowSessionExport.sessions[].heartRate.durationAudit\",\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis\",\"\$.trainFlowSessionExport.sessions[].execution.phases[]\"]},\n{\"id\":\"QR15\",\"description\":\"sessionReasons按QR01..QR14所列reason固定顺序；phaseReasons按phaseSequence再reason顺序，无重复pair，引用同snapshot真实closed phase。no-eligible可与真实sample-axis原因并存，不因top status而删原因。normal/no-eligible禁止insufficient_coverage/partial_coverage；available或eligible=0禁止unavailable_no_effective_max。正时长原因必须严格positive；其余为显式null。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].heartRate.originalAnalysis.qualityReasons\"]},\n{\"id\":\"SEL-01\",\"description\":\"sessions至少一场，sessionId唯一且逐项等于selection.includedSessionIds，顺序为本次冻结选择。source=single_session表示单场入口，calendar也可只选一场。selectionScope=user_selected_subset：未选某场或文件中没有某日，不表示那天没有训练。同一历史planId的多场仍保留各自snapshot，合并显示组也不变成一个原session。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.selection\",\"\$.trainFlowSessionExport.sessions\"]},\n{\"id\":\"SEL-02\",\"description\":\"两日期同时null表示不限制日期，否则startDateInclusive<=endDateInclusive且包含首尾；场次整场按冻结startLocalDate选择，不在午夜截断。modeFilter/planFilter为null表示无筛选限制，否则非空且无重复，mode按timed/strength/follow_along、planId按字典序。includedUnknownDateSessionIds是实际included中startLocalDate未知的精确子集并保持相对顺序；可与日期过滤共存但不冒充日期匹配。无planId只可在无计划限制时入选。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.selection\",\"\$.",
    "trainFlowSessionExport.sessions[].session.timeMetadata\",\"\$.trainFlowSessionExport.sessions[].session.planId\"]},\n{\"id\":\"TIME-01\",\"description\":\"sourceContractVersion=1时startLocalDate/startZoneId/startUtcOffsetSeconds/sourceContractVersion四值齐全，表示Start当时冻结观测依据；否则四项为null，不能用当前时区补齐。startTimestampBasis/endTimestampBasis的observed表示新来源真实观测，legacy_stored表示已有旧持久化值但无新采集证据，unknown对应没有可证明时刻且原timestamp为null。process_interrupted的实际结束未知时endedAt仍null。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].session.timeMetadata\",\"\$.trainFlowSessionExport.sessions[].session.startedAt\",\"\$.trainFlowSessionExport.sessions[].session.endedAt\"]},\n{\"id\":\"TIME-02\",\"description\":\"trustedEndAtBasis=start_anchor_plus_trusted_offset时，trustedEndAtUtc为开始锚点加canonical可信endOffsetMs，使用checked加法；缺任一依据时basis=unavailable且值null。它是derived，可能不同于实际endedAt，不能覆盖observed。raw offset是session单调时间，不表示每点额外观测了墙钟；start+offset只能称推导时刻。训练后改变系统时钟或时区不改原排序/历史日，不用重启或最后写入时刻补未知尾段。\",\"relatedPaths\":[\"\$.trainFlowSessionExport.sessions[].session.timeMetadata\",\"\$.trainFlowSessionExport.sessions[].heartRate.samples[]\",\"\$.trainFlowSessionExport.sessions[].execution.phases[]\"]}\n]\n}"
